window.CS50KZ_MATH_EXAM.precalc = [{"id":"m1-1-val:0","l":1,"lvl":"easy","type":"num","ctx":"Функцияның мәнін есептеу. $f(x)=3x^2-2x+1$ функциясы берілген. Жауапты санмен немесе бөлшекпен (мысалы, 3/4) жазыңыз.","q":"$f(2)$ неге тең?","a":9},{"id":"m1-1-val:1","l":1,"lvl":"easy","type":"num","ctx":"Функцияның мәнін есептеу. $f(x)=3x^2-2x+1$ функциясы берілген. Жауапты санмен немесе бөлшекпен (мысалы, 3/4) жазыңыз.","q":"$f(-2)$ неге тең?","a":17},{"id":"m1-1-val:2","l":1,"lvl":"easy","type":"num","ctx":"Функцияның мәнін есептеу. $f(x)=3x^2-2x+1$ функциясы берілген. Жауапты санмен немесе бөлшекпен (мысалы, 3/4) жазыңыз.","q":"$f\\left(\\tfrac12\\right)$ неге тең?","a":"3/4"},{"id":"m1-1-tf:0","l":1,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$x^2+y^2=4$ теңдеуі $y$-ті $x$-тің функциясы ретінде анықтайды.","a":false,"e":"Жалған: $x=0$ үшін $y=2$ және $y=-2$ екеуі де қанағаттандырады. Бір аргументке екі мән сәйкес келеді."},{"id":"m1-1-tf:1","l":1,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$f(x)=x^3$ - тақ функция.","a":true,"e":"Ақиқат: $(-x)^3=-x^3=-f(x)$."},{"id":"m1-1-tf:2","l":1,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$f(x)=|x|$ - жұп функция.","a":true,"e":"Ақиқат: $|-x|=|x|$."},{"id":"m1-1-tf:3","l":1,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"Функция графигін кез келген тік түзу ең көбі бір нүктеде қиып өтеді.","a":true,"e":"Ақиқат: бұл тік түзу тесті (Теорема 1.1). Бір аргументке бір мән сәйкес келеді."},{"id":"m1-1-tf:4","l":1,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$f(x)=x^2$ функциясының анықталу облысы - $x\\ge0$.","a":false,"e":"Жалған: квадраттауға кез келген нақты сан жарайды, сондықтан $D(f)=(-\\infty;+\\infty)$. $x\\ge0$ шарты мәндер жиыны $E(f)=[0;+\\infty)$ үшін ғана орынды."},{"id":"m1-1-pick:0","l":1,"lvl":"easy","type":"choice","ctx":"Функция екенін тану және еңіс. Дұрыс жауапты таңдаңыз. Бірінші сұрақта бірнеше жауап дұрыс болуы мүмкін.","q":"Төмендегі сәйкестіктердің қайсысы $\\{1,2,3\\}$ жиынында анықталған функция болады? Дұрыс жауаптардың барлығын белгілеңіз.","o":["$1\\to5,\\ 2\\to5,\\ 3\\to7$","$1\\to4,\\ 1\\to6,\\ 2\\to5,\\ 3\\to5$","$1\\to9,\\ 2\\to8,\\ 3\\to7$","$1\\to2,\\ 2\\to3$"],"a":[0,2],"e":"Бірінші және үшінші сәйкестікте әр аргументке бір мән сәйкес. Екіншіде 1-ге екі мән берілген. Төртіншіде 3 санына мән жоқ."},{"id":"m1-1-pick:1","l":1,"lvl":"easy","type":"choice","ctx":"Функция екенін тану және еңіс. Дұрыс жауапты таңдаңыз. Бірінші сұрақта бірнеше жауап дұрыс болуы мүмкін.","q":"$f(x)=-2x+7$ функциясы - түзу. Оның еңісі қандай?","o":["$7$","$-2$","$2$","$-7$"],"a":1,"e":"$f(x)=kx+b$ түрінде $k=-2$ - еңіс, $b=7$ - $Oy$ осімен қиылысу ординатасы."},{"id":"m1-1-dom:0","l":1,"lvl":"medium","type":"interval","ctx":"Анықталу облысы. Облысты аралық түрінде жазыңыз. Шексіздік - oo, бірігу - U белгісі (мысалы, $(-\\infty;\\,2]\\cup(5;\\,+\\infty)$ үшін: (-oo; 2] U (5; oo)).","q":"$f(x)=\\dfrac{\\sqrt{x-1}}{x-3}$","a":"[1; 3) U (3; oo)"},{"id":"m1-1-dom:1","l":1,"lvl":"medium","type":"interval","ctx":"Анықталу облысы. Облысты аралық түрінде жазыңыз. Шексіздік - oo, бірігу - U белгісі (мысалы, $(-\\infty;\\,2]\\cup(5;\\,+\\infty)$ үшін: (-oo; 2] U (5; oo)).","q":"$g(x)=\\sqrt{4-x^2}$","a":"[-2; 2]"},{"id":"m1-1-dom:2","l":1,"lvl":"medium","type":"interval","ctx":"Анықталу облысы. Облысты аралық түрінде жазыңыз. Шексіздік - oo, бірігу - U белгісі (мысалы, $(-\\infty;\\,2]\\cup(5;\\,+\\infty)$ үшін: (-oo; 2] U (5; oo)).","q":"$h(x)=\\dfrac{1}{x^2-x-6}$","a":"(-oo; -2) U (-2; 3) U (3; oo)"},{"id":"m1-1-vertex:0","l":1,"lvl":"medium","type":"num","ctx":"Параболаның төбесі. Жауапты санмен жазыңыз.","q":"$f(x)=2x^2-12x+7$ параболасы төбесінің абсциссасы неге тең?","a":3},{"id":"m1-1-vertex:1","l":1,"lvl":"medium","type":"num","ctx":"Параболаның төбесі. Жауапты санмен жазыңыз.","q":"Сол параболаның төбесіндегі мән (ордината) неге тең?","a":-11},{"id":"m1-1-vertex:2","l":1,"lvl":"medium","type":"num","ctx":"Параболаның төбесі. Жауапты санмен жазыңыз.","q":"$f(x)=-x^2+4x+1$ функциясының ең үлкен мәні неге тең?","a":5},{"id":"m1-1-comp:0","l":1,"lvl":"medium","type":"expr","ctx":"Құрама және кері функцияны жазу. Өрнекті $x$ арқылы жазыңыз. Көбейту: 2x не 2*x, дәреже: x^2, бөлшек: (x+6)/3. Эквивалентті түрдегі кез келген дұрыс жауап қабылданады.","q":"$f(x)=2x+1$, $g(x)=x^2-3$. $(f\\circ g)(x)=\\ ?$","a":"2*x^2-5"},{"id":"m1-1-comp:1","l":1,"lvl":"medium","type":"expr","ctx":"Құрама және кері функцияны жазу. Өрнекті $x$ арқылы жазыңыз. Көбейту: 2x не 2*x, дәреже: x^2, бөлшек: (x+6)/3. Эквивалентті түрдегі кез келген дұрыс жауап қабылданады.","q":"Сол $f$ және $g$ үшін $(g\\circ f)(x)=\\ ?$ (жақшаны ашып жазуға болады, ашпаса да болады)","a":"4*x^2+4*x-2"},{"id":"m1-1-comp:2","l":1,"lvl":"medium","type":"expr","ctx":"Құрама және кері функцияны жазу. Өрнекті $x$ арқылы жазыңыз. Көбейту: 2x не 2*x, дәреже: x^2, бөлшек: (x+6)/3. Эквивалентті түрдегі кез келген дұрыс жауап қабылданады.","q":"$f(x)=3x-6$. Кері функция $f^{-1}(x)=\\ ?$","a":"(x+6)/3"},{"id":"m1-1-table:0","l":1,"lvl":"medium","type":"matrix","ctx":"Мәндер кестесін толтыру. $f(x)=x^2-2x$ функциясы берілген. Ұяшықтарға сандарды жазыңыз.","q":"$x=-1,\\,0,\\,1,\\,2,\\,3$ нүктелеріндегі мәндерді жол түрінде жазыңыз.","orient":"row","name":"$f(x)$:","a":[3,0,-1,0,3]},{"id":"m1-1-table:1","l":1,"lvl":"medium","type":"matrix","ctx":"Мәндер кестесін толтыру. $f(x)=x^2-2x$ функциясы берілген. Ұяшықтарға сандарды жазыңыз.","q":"$\\begin{pmatrix} f(0) & f(1)\\\\ f(2) & f(3)\\end{pmatrix}$ матрицасын толтырыңыз.","name":"$M=$","a":[[0,-1],[0,3]]},{"id":"m1-1-read:0","l":1,"lvl":"medium","type":"choice","ctx":"Графикті оқу және түрлендіру. Дұрыс жауапты таңдаңыз. Үшінші сұрақта бірнеше жауап дұрыс.","q":"$y=-(x-2)^2+3$ параболасының төбесі қай нүктеде?","o":["$(2;\\,3)$","$(-2;\\,3)$","$(2;\\,-3)$","$(3;\\,2)$"],"a":0,"e":"Төбелік түр $a(x-m)^2+n$ бойынша $m=2$, $n=3$."},{"id":"m1-1-read:1","l":1,"lvl":"medium","type":"choice","ctx":"Графикті оқу және түрлендіру. Дұрыс жауапты таңдаңыз. Үшінші сұрақта бірнеше жауап дұрыс.","q":"$y=f(x+3)$ графигі $y=f(x)$ графигінен қалай алынады?","o":["3 бірлікке оңға жылжыту","3 бірлікке солға жылжыту","3 бірлікке жоғары жылжыту","$Oy$ осі бойынша шағылдыру"],"a":1,"e":"Жаңа графикте $f(x_0)$ мәні $x=x_0-3$ нүктесінде шығады: график солға жылжыған."},{"id":"m1-1-read:2","l":1,"lvl":"medium","type":"choice","ctx":"Графикті оқу және түрлендіру. Дұрыс жауапты таңдаңыз. Үшінші сұрақта бірнеше жауап дұрыс.","q":"Жұп функцияларды белгілеңіз.","o":["$x^4+1$","$x^3+x$","$|x|-x^2$","$x^2+x$","$5$"],"a":[0,2,4],"e":"$x^3+x$ тақ, $x^2+x$ жұп та, тақ та емес. Тұрақты $5$ үшін $f(-x)=5=f(x)$, яғни жұп."},{"id":"m1-1-inv:0","l":1,"lvl":"hard","type":"expr","ctx":"Бөлшек-сызықтық функцияның кері функциясы. Өрнекті $x$ арқылы жазыңыз.","q":"$f(x)=\\dfrac{2x+1}{x-3}$. $f^{-1}(x)=\\ ?$","a":"(3*x+1)/(x-2)"},{"id":"m1-1-line:0","l":1,"lvl":"hard","type":"expr","ctx":"Екі нүкте арқылы өтетін түзудің теңдеуі. Теңдеуді $y=\\dots$ түрінде не $ax+by+c=0$ түрінде жазыңыз (эквивалентті теңдеулер қабылданады).","q":"$A(1;\\,2)$ және $B(3;\\,8)$ нүктелері арқылы өтетін түзудің теңдеуі.","eq":true,"a":"y=3*x-1"},{"id":"m1-1-line:1","l":1,"lvl":"hard","type":"expr","ctx":"Екі нүкте арқылы өтетін түзудің теңдеуі. Теңдеуді $y=\\dots$ түрінде не $ax+by+c=0$ түрінде жазыңыз (эквивалентті теңдеулер қабылданады).","q":"$C(-1;\\,4)$ және $D(2;\\,-2)$ нүктелері арқылы өтетін түзудің теңдеуі.","eq":true,"a":"y=-2*x+2"},{"id":"m1-1-slope:0","l":1,"lvl":"hard","type":"num","ctx":"Еңіс және түзудің мәні. Жауапты санмен жазыңыз.","q":"$A(-2;\\,5)$ және $B(4;\\,-7)$ нүктелері арқылы өтетін түзудің еңісі.","a":-2},{"id":"m1-1-slope:1","l":1,"lvl":"hard","type":"num","ctx":"Еңіс және түзудің мәні. Жауапты санмен жазыңыз.","q":"Сол түзудің $x=10$ нүктесіндегі ординатасы.","a":-19},{"id":"m1-1-count:0","l":1,"lvl":"hard","type":"num","ctx":"Облыстағы бүтін сандар. Жауапты бүтін санмен жазыңыз.","q":"$f(x)=\\dfrac{\\sqrt{10-x^2}}{x-1}$ функциясының анықталу облысына қанша бүтін сан кіреді?","a":6},{"id":"m1-1-parity:0","l":1,"lvl":"hard","type":"expr","ctx":"Жұп бөлікті табу. Жауапты $x$ арқылы жазыңыз. Теорема 1.2 бойынша $f_e(x)=\\frac{f(x)+f(-x)}{2}$.","q":"$f(x)=x^3+x^2$ функциясының жұп бөлігі $f_e(x)=\\ ?$","a":"x^2"},{"id":"m1-1-parity:1","l":1,"lvl":"hard","type":"expr","ctx":"Жұп бөлікті табу. Жауапты $x$ арқылы жазыңыз. Теорема 1.2 бойынша $f_e(x)=\\frac{f(x)+f(-x)}{2}$.","q":"$f(x)=x^5-3x^4+2x$ функциясының жұп бөлігі $f_e(x)=\\ ?$","a":"-3*x^4"},{"id":"m1-1-range:0","l":1,"lvl":"hard","type":"interval","ctx":"Мәндер жиыны. Аралық түрінде жазыңыз: (-oo; 5] сияқты.","q":"$f(x)=-x^2+4x+1$ функциясының мәндер жиыны $E(f)$.","a":"(-oo; 5]"},{"id":"m1-1-range:1","l":1,"lvl":"hard","type":"interval","ctx":"Мәндер жиыны. Аралық түрінде жазыңыз: (-oo; 5] сияқты.","q":"Сол функцияның $[0;\\,3]$ кесіндісіндегі мәндер жиыны.","a":"[1; 5]"},{"id":"w0-q0","l":1,"lvl":"quiz","type":"choice","q":"f(x) = √(x − 2) функциясының анықталу облысы қандай?","o":["x > 2","x ≥ 2","x ≤ 2","барлық нақты сандар"],"a":1,"e":"Түбір астындағы өрнек теріс болмайды: x − 2 ≥ 0, яғни x ≥ 2. Қатаң емес теңсіздік, өйткені √0 = 0 анықталған."},{"id":"w0-q1","l":1,"lvl":"quiz","type":"choice","q":"f(x) = 1/(x² − 9) функциясының облысына қай сандар кірмейді?","o":["тек 3","тек −3","3 және −3","9"],"a":2,"e":"Бөлгіш нөл болады: x² − 9 = 0, x = 3 не x = −3. Екеуі де алынып тасталады."},{"id":"w0-q2","l":1,"lvl":"quiz","type":"choice","q":"f(x) = x⁴ − x² функциясы қандай?","o":["жұп","тақ","жұп та, тақ та емес","бір мезгілде жұп та, тақ та"],"a":0,"e":"f(−x) = (−x)⁴ − (−x)² = x⁴ − x² = f(x): жұп. Тақ болу үшін f(−x) = −f(x) керек еді, ол орындалмайды."},{"id":"w0-q3","l":1,"lvl":"quiz","type":"choice","q":"f(x) = x² − 6x + 5 параболасы төбесінің абсциссасы неге тең?","o":["−3","5","6","3"],"a":3,"e":"x_в = −b/(2a) = −(−6)/(2·1) = 3. Тексеру: f(3) = 9 − 18 + 5 = −4 - ең кіші мән."},{"id":"w0-q4","l":1,"lvl":"quiz","type":"choice","q":"f(x) = 2x + 1, g(x) = x − 4 болса, (f∘g)(x) неге тең?","o":["2x − 3","2x − 7","2x + 5","x − 3"],"a":1,"e":"f(g(x)) = 2(x − 4) + 1 = 2x − 7. Ал (g∘f)(x) = (2x + 1) − 4 = 2x − 3, яғни реті маңызды."},{"id":"w0-q5","l":1,"lvl":"quiz","type":"choice","q":"f(x) = 3x − 6 функциясының кері функциясы қандай?","o":["(x + 6)/3","(x − 6)/3","3x + 6","1/(3x − 6)"],"a":0,"e":"y = 3x − 6 ⇒ x = (y + 6)/3. Әріптерді ауыстырсақ, f⁻¹(x) = (x + 6)/3. 1/f(x) кері функция емес."},{"id":"w0-q6","l":1,"lvl":"quiz","type":"choice","q":"Төмендегі теңдеулердің қайсысы y-ті x-тің функциясы ретінде анықтамайды?","o":["y = x²","y = |x|","x = y²","y = 1/x"],"a":2,"e":"x = y² теңдеуінде x = 4 үшін y = 2 және y = −2: бір аргументке екі мән. Қалғандарында әр x үшін бір ғана y."},{"id":"w0-q7","l":1,"lvl":"quiz","type":"choice","q":"y = f(x + 3) графигі y = f(x) графигінен қалай алынады?","o":["3 бірлік оңға","3 бірлік жоғары","3 бірлік төмен","3 бірлік солға"],"a":3,"e":"f(x + 3) мәні x₀ нүктесіндегі f мәніне x = x₀ − 3 болғанда тең, сондықтан график 3 бірлік солға жылжиды."},{"id":"m1-2-formulas:0","l":2,"lvl":"easy","type":"num","ctx":"Қысқаша көбейту формулалары. Жауапты санмен жазыңыз.","q":"$51^2-49^2$ мәнін есептеңіз (формуланы қолданыңыз).","a":200},{"id":"m1-2-formulas:1","l":2,"lvl":"easy","type":"num","ctx":"Қысқаша көбейту формулалары. Жауапты санмен жазыңыз.","q":"$x+y=10$, $xy=21$ болса, $x^2+y^2$ неге тең?","a":58},{"id":"m1-2-formulas:2","l":2,"lvl":"easy","type":"num","ctx":"Қысқаша көбейту формулалары. Жауапты санмен жазыңыз.","q":"$x-\\dfrac1x=3$ болса, $x^2+\\dfrac1{x^2}$ неге тең?","a":11},{"id":"m1-2-tf:0","l":2,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$(a+b)^2=a^2+b^2$ барлық $a$, $b$ үшін орындалады.","a":false,"e":"Жалған: $(a+b)^2=a^2+2ab+b^2$. Мысалы $a=b=1$: $4\\ne2$."},{"id":"m1-2-tf:1","l":2,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$x^2-9=(x-3)(x+3)$ - тепе-теңдік.","a":true,"e":"Ақиқат: жақшаны ашсақ, $x^2+3x-3x-9=x^2-9$. Бұл кез келген $x$ үшін дұрыс."},{"id":"m1-2-tf:2","l":2,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"Егер $D&lt;0$ болса, $ax^2+bx+c=0$ теңдеуінің нақты түбірлері жоқ.","a":true,"e":"Ақиқат: толық квадраттан $\\left(x+\\frac{b}{2a}\\right)^2=\\frac{D}{4a^2}&lt;0$, ал нақты санның квадраты теріс болмайды."},{"id":"m1-2-tf:3","l":2,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$x^2=9$ теңдеуінің жалғыз шешімі $x=3$.","a":false,"e":"Жалған: $x=-3$ те шешім, себебі $(-3)^2=9$."},{"id":"m1-2-tf:4","l":2,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$|x|&lt;-2$ теңсіздігінің шешімі жоқ.","a":true,"e":"Ақиқат: модуль әрдайым теріс емес, сондықтан $-2$-ден кіші бола алмайды."},{"id":"m1-2-pick:0","l":2,"lvl":"easy","type":"choice","ctx":"Дискриминант және түбірлер саны. Дұрыс жауапты таңдаңыз.","q":"$x^2-6x+9=0$ теңдеуінің түбірлері туралы қандай тұжырым дұрыс?","o":["екі түрлі нақты түбір бар","жалғыз (еселігі екі) түбір $x=3$","нақты түбір жоқ","екі түбір: $3$ және $-3$"],"a":1,"e":"$D=36-36=0$, түбір $x=-\\frac{b}{2a}=3$. Сондай-ақ $x^2-6x+9=(x-3)^2$."},{"id":"m1-2-pick:1","l":2,"lvl":"easy","type":"choice","ctx":"Дискриминант және түбірлер саны. Дұрыс жауапты таңдаңыз.","q":"$x^2+x+1=0$ теңдеуінің нақты түбірі нешеу?","o":["0","1","2","3"],"a":0,"e":"$D=1-4=-3&lt;0$, нақты түбір жоқ."},{"id":"m1-2-pick:2","l":2,"lvl":"easy","type":"choice","ctx":"Дискриминант және түбірлер саны. Дұрыс жауапты таңдаңыз.","q":"Қай теңдеудің түбірлерінің қосындысы $7$, көбейтіндісі $10$?","o":["$x^2-7x+10=0$","$x^2+7x+10=0$","$x^2-10x+7=0$","$x^2+7x-10=0$"],"a":0,"e":"Кері Виет теоремасы: $x^2-sx+q=0$, $s=7$, $q=10$. Түбірлері $2$ және $5$."},{"id":"m1-2-vieta1:0","l":2,"lvl":"easy","type":"num","ctx":"Виет теоремасы. Жауапты санмен жазыңыз.","q":"$x^2-9x+14=0$ теңдеуі түбірлерінің қосындысы.","a":9},{"id":"m1-2-vieta1:1","l":2,"lvl":"easy","type":"num","ctx":"Виет теоремасы. Жауапты санмен жазыңыз.","q":"Сол теңдеу түбірлерінің көбейтіндісі.","a":14},{"id":"m1-2-vieta1:2","l":2,"lvl":"easy","type":"num","ctx":"Виет теоремасы. Жауапты санмен жазыңыз.","q":"Сол теңдеудің кіші түбірі.","a":2},{"id":"m1-2-simplify:0","l":2,"lvl":"medium","type":"expr","ctx":"Бөлшекті ықшамдау. Өрнекті ықшамдап $x$ арқылы жазыңыз. Көбейту: 2x не 2*x, дәреже: x^2, бөлшек: (x-3)/(x+3).","q":"$\\dfrac{x^2-9}{x^2+6x+9}$ ықшамдаңыз.","a":"(x-3)/(x+3)","dom":[0.2,6]},{"id":"m1-2-simplify:1","l":2,"lvl":"medium","type":"expr","ctx":"Бөлшекті ықшамдау. Өрнекті ықшамдап $x$ арқылы жазыңыз. Көбейту: 2x не 2*x, дәреже: x^2, бөлшек: (x-3)/(x+3).","q":"$\\dfrac{x^3-8}{x-2}$ ықшамдаңыз.","a":"x^2+2*x+4","dom":[2.5,6]},{"id":"m1-2-simplify:2","l":2,"lvl":"medium","type":"expr","ctx":"Бөлшекті ықшамдау. Өрнекті ықшамдап $x$ арқылы жазыңыз. Көбейту: 2x не 2*x, дәреже: x^2, бөлшек: (x-3)/(x+3).","q":"$\\dfrac1{x-1}-\\dfrac1{x+1}$ өрнегін бір бөлшек етіп жазыңыз.","a":"2/(x^2-1)","dom":[1.5,6]},{"id":"m1-2-quadineq:0","l":2,"lvl":"medium","type":"interval","ctx":"Квадрат теңсіздіктер. Шешімді аралық түрінде жазыңыз (шексіздік - oo, бірігу - U, барлық сан - R).","q":"$x^2-5x+6&lt;0$","a":"(2; 3)"},{"id":"m1-2-quadineq:1","l":2,"lvl":"medium","type":"interval","ctx":"Квадрат теңсіздіктер. Шешімді аралық түрінде жазыңыз (шексіздік - oo, бірігу - U, барлық сан - R).","q":"$x^2-2x-8>0$","a":"(-oo; -2) U (4; oo)"},{"id":"m1-2-quadineq:2","l":2,"lvl":"medium","type":"interval","ctx":"Квадрат теңсіздіктер. Шешімді аралық түрінде жазыңыз (шексіздік - oo, бірігу - U, барлық сан - R).","q":"$x^2+2x+5>0$","a":"R"},{"id":"m1-2-modineq:0","l":2,"lvl":"medium","type":"interval","ctx":"Модульді теңсіздіктер. Шешімді аралық түрінде жазыңыз.","q":"$|2x-1|&lt;5$","a":"(-2; 3)"},{"id":"m1-2-modineq:1","l":2,"lvl":"medium","type":"interval","ctx":"Модульді теңсіздіктер. Шешімді аралық түрінде жазыңыз.","q":"$|x+2|\\ge3$","a":"(-oo; -5] U [1; oo)"},{"id":"m1-2-modineq:2","l":2,"lvl":"medium","type":"interval","ctx":"Модульді теңсіздіктер. Шешімді аралық түрінде жазыңыз.","q":"$|x-4|\\le0$","a":"[4; 4]"},{"id":"m1-2-modeq:0","l":2,"lvl":"medium","type":"num","ctx":"Модульді теңдеу. Жауапты санмен жазыңыз.","q":"$|x-2|=|3x+4|$ теңдеуі шешімдерінің қосындысы.","a":"-7/2"},{"id":"m1-2-modeq:1","l":2,"lvl":"medium","type":"num","ctx":"Модульді теңдеу. Жауапты санмен жазыңыз.","q":"$|3x-6|=9$ теңдеуінің оң түбірі.","a":5},{"id":"m1-2-expand:0","l":2,"lvl":"medium","type":"matrix","ctx":"Көпмүшенің коэффициенттері. Коэффициенттерді жол түрінде (жоғарғы дәрежеден бастап) жазыңыз.","q":"$(x-1)(x+2)(x-3)$ көбейтіндісін ашып, $x^3+\\dots$ коэффициенттерін жазыңыз.","orient":"row","name":"$[x^3,\\,x^2,\\,x,\\,1]$:","a":[1,-2,-5,6]},{"id":"m1-2-irr:0","l":2,"lvl":"medium","type":"choice","ctx":"Бөгде түбірлер. Дұрыс жауапты таңдаңыз.","q":"$\\sqrt{x+6}=x$ теңдеуін квадраттағанда $x^2-x-6=0$ шығады. Қай мән бастапқы теңдеудің шешімі?","o":["тек $x=3$","тек $x=-2$","$x=3$ және $x=-2$","шешімі жоқ"],"a":0,"e":"$x=-2$ үшін сол жағы $\\sqrt4=2$, оң жағы $-2$: бөгде түбір. $x=3$: $\\sqrt9=3$."},{"id":"m1-2-irr:1","l":2,"lvl":"medium","type":"choice","ctx":"Бөгде түбірлер. Дұрыс жауапты таңдаңыз.","q":"Мына түрлендірулердің қайсысы бөгде түбір келтіруі мүмкін? Дұрыс жауаптардың барлығын белгілеңіз.","o":["екі жағын квадраттау","екі жағына бірдей санды қосу","екі жағын $x$-ті қамтитын өрнекке көбейту","екі жағын нөлден өзге санға бөлу"],"a":[0,2],"e":"Квадраттау ($u=v\\Rightarrow u^2=v^2$ қайтымсыз) және айнымалы өрнекке көбейту (өрнек нөл болғанда) бөгде түбір береді. Қалғандары қайтымды."},{"id":"m1-2-vieta-eq:0","l":2,"lvl":"medium","type":"expr","ctx":"Теңдеуді түбірлері бойынша құру. Жауапты $x$ арқылы жазыңыз (бас коэффициент 1).","q":"Түбірлері $2+\\sqrt3$ және $2-\\sqrt3$ болатын келтірілген квадрат теңдеудің сол жағын жазыңыз: $x^2+bx+c$.","a":"x^2-4*x+1"},{"id":"m1-2-irrat:0","l":2,"lvl":"hard","type":"num","ctx":"Иррационал теңдеулер. Тексеруді ұмытпаңыз. Жауапты санмен жазыңыз.","q":"$\\sqrt{2x+3}=x$ теңдеуінің шешімі.","a":3},{"id":"m1-2-irrat:1","l":2,"lvl":"hard","type":"num","ctx":"Иррационал теңдеулер. Тексеруді ұмытпаңыз. Жауапты санмен жазыңыз.","q":"$\\sqrt{x+7}-1=x$ теңдеуінің шешімі.","a":2},{"id":"m1-2-ratineq:0","l":2,"lvl":"hard","type":"interval","ctx":"Рационал теңсіздік. Шешімді аралық түрінде жазыңыз.","q":"$\\dfrac{x-1}{x^2-x-6}\\le0$","a":"(-oo; -2) U [1; 3)"},{"id":"m1-2-ratineq:1","l":2,"lvl":"hard","type":"interval","ctx":"Рационал теңсіздік. Шешімді аралық түрінде жазыңыз.","q":"$\\dfrac{x+1}{x-2}>3$","a":"(2; 7/2)"},{"id":"m1-2-tf-hard:0","l":2,"lvl":"hard","type":"tf","ctx":"Теңсіздік пен модуль: түсіну. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$a&lt;b$ болса, әрдайым $a^2&lt;b^2$.","a":false,"e":"Жалған: $a=-3$, $b=2$ үшін $a&lt;b$, ал $9>4$. Квадраттау тек екі сан да теріс емес болғанда таңбаны сақтайды."},{"id":"m1-2-tf-hard:1","l":2,"lvl":"hard","type":"tf","ctx":"Теңсіздік пен модуль: түсіну. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$|a+b|=|a|+|b|$ теңдігі тек $ab\\ge0$ болғанда орындалады.","a":true,"e":"Ақиқат: 4-қорыту. Теңдік $uv=|uv|$ болғанда ғана."},{"id":"m1-2-tf-hard:2","l":2,"lvl":"hard","type":"tf","ctx":"Теңсіздік пен модуль: түсіну. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$x+\\dfrac1x\\ge2$ барлық нақты $x\\ne0$ үшін орындалады.","a":false,"e":"Жалған: теңсіздік тек $x>0$ болғанда ($x=-1$ үшін $-2$). Теріс $x$ үшін $x+\\frac1x\\le-2$."},{"id":"m1-2-tf-hard:3","l":2,"lvl":"hard","type":"tf","ctx":"Теңсіздік пен модуль: түсіну. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$x^2-4x+4\\ge0$ теңсіздігі барлық нақты сан үшін орындалады.","a":true,"e":"Ақиқат: $x^2-4x+4=(x-2)^2\\ge0$, теңдік $x=2$-де."},{"id":"w1-q0","l":2,"lvl":"quiz","type":"choice","q":"x² − 5x + 6 = 0 теңдеуінің түбірлерінің қосындысы неге тең?","o":["−5","5","6","−6"],"a":1,"e":"Виет теоремасы бойынша x₁ + x₂ = −b/a = 5. Түбірлері 2 және 3."},{"id":"w1-q1","l":2,"lvl":"quiz","type":"choice","q":"x² + 4x + 5 = 0 теңдеуінің нақты түбірлері қанша?","o":["нақты түбір жоқ","біреу","екеу","төртеу"],"a":0,"e":"D = 16 − 20 = −4 < 0, сондықтан нақты түбір жоқ."},{"id":"w1-q2","l":2,"lvl":"quiz","type":"choice","q":"|x − 2| < 3 теңсіздігінің шешімі қандай?","o":["x < 5","−1 < x < 5","x < −1 не x > 5","x > −1"],"a":1,"e":"−3 < x − 2 < 3 теңсіздігін шешеміз: −1 < x < 5."},{"id":"w1-q3","l":2,"lvl":"quiz","type":"choice","q":"x³ − 8 өрнегінің дұрыс жіктелуі қайсы?","o":["(x − 2)(x² + 4)","(x − 2)(x² − 2x + 4)","(x + 2)(x² − 2x + 4)","(x − 2)(x² + 2x + 4)"],"a":3,"e":"a³ − b³ = (a − b)(a² + ab + b²), a = x, b = 2: (x − 2)(x² + 2x + 4)."},{"id":"w1-q4","l":2,"lvl":"quiz","type":"choice","q":"x² − 3x + k = 0 теңдеуінің түбірлері x₁, x₂ және x₁² + x₂² = 5 болса, k неге тең?","o":["1","2","3","−2"],"a":1,"e":"x₁² + x₂² = 9 − 2k = 5, бұдан k = 2 (түбірлері 1 және 2)."},{"id":"w1-q5","l":2,"lvl":"quiz","type":"choice","q":"√(x + 6) = x теңдеуінің шешімі қайсы?","o":["x = 3","x = 3 және x = −2","x = −2","шешімі жоқ"],"a":0,"e":"Квадраттасақ x² − x − 6 = 0, x = 3 не x = −2. x = −2 бөгде: √4 = 2 ≠ −2. Жауап x = 3."},{"id":"w1-q6","l":2,"lvl":"quiz","type":"choice","q":"(x − 1)(x + 3)/(x − 2) ≥ 0 теңсіздігінде x = 2 нүктесі шешімге кіре ме?","o":["иә, өйткені теңсіздік қатаң емес","жоқ, өйткені бөлгіш нөл болады","тек x = 1 кіреді","иә, өйткені алым нөл"],"a":1,"e":"Бөлшектің бөлгіші нөл болатын нүкте әрдайым алынып тасталады, теңсіздік қатаң емес болса да. Алымның нөлдері x = 1 және x = −3 кіреді."},{"id":"w1-q7","l":2,"lvl":"quiz","type":"choice","q":"Қай пікір дұрыс?","o":["a < b ⇒ a² < b² әрдайым","x² = 16 ⇒ x = 4","x + 1/x ≥ 2, егер x > 0","|a + b| = |a| + |b| әрдайым"],"a":2,"e":"x > 0 үшін x + 1/x ≥ 2 (орташа мәндер теңсіздігі). Қалғандары жалған: a = −3, b = 2; x = −4 те шешім; a = 3, b = −5 үшін 2 ≠ 8."},{"id":"m1-3-bezout:0","l":3,"lvl":"easy","type":"num","ctx":"Безу теоремасы: қалдықты бөлместен табу. Жауапты санмен жазыңыз.","q":"$x^3-2x^2+x-5$ көпмүшелігін $x-2$-ге бөлгендегі қалдық.","a":-3},{"id":"m1-3-bezout:1","l":3,"lvl":"easy","type":"num","ctx":"Безу теоремасы: қалдықты бөлместен табу. Жауапты санмен жазыңыз.","q":"$x^3+4x^2-x+1$ көпмүшелігін $x+1$-ге бөлгендегі қалдық.","a":5},{"id":"m1-3-bezout:2","l":3,"lvl":"easy","type":"num","ctx":"Безу теоремасы: қалдықты бөлместен табу. Жауапты санмен жазыңыз.","q":"$P(x)=x^3-6x^2+11x-6$ үшін $P(1)+P(2)+P(3)$ неге тең?","a":0},{"id":"m1-3-tf:0","l":3,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$\\deg(P\\cdot Q)=\\deg P+\\deg Q$.","a":true,"e":"Ақиқат: бас мүшелердің көбейтіндісі нөл емес, дәрежелері қосылады. Мысалы $(x^2+1)(x^3-x)$ дәрежесі 5."},{"id":"m1-3-tf:1","l":3,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$P(x)=x^4+1$ көпмүшелігінің кемінде бір нақты түбірі бар.","a":false,"e":"Жалған: $x^4\\ge0$, демек $x^4+1\\ge1&gt;0$. Жұп дәрежелі көпмүшелік нақты түбірсіз болуы мүмкін."},{"id":"m1-3-tf:2","l":3,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"Тақ дәрежелі көпмүшеліктің әрдайым кемінде бір нақты түбірі бар.","a":true,"e":"Ақиқат: екі шетінде мәндері қарама-қарсы таңбалы және график үзіліссіз."},{"id":"m1-3-tf:3","l":3,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$\\dfrac{x^2-1}{x-1}$ функциясының $x=1$ нүктесінде тік асимптотасы бар.","a":false,"e":"Жалған: $x\\ne1$ үшін бөлшек $x+1$-ге тең, $x=1$ - тесік (ордината $2$)."},{"id":"m1-3-tf:4","l":3,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$\\dfrac{3x^2+1}{x^2-4}$ функциясының көлденең асимптотасы $y=3$.","a":true,"e":"Ақиқат: екі көпмүшелік те екінші дәрежелі, бас коэффициенттер қатынасы $\\frac31$."},{"id":"m1-3-pick:0","l":3,"lvl":"easy","type":"choice","ctx":"Асимптоталар мен түбірлер. Дұрыс жауапты таңдаңыз.","q":"$f(x)=\\dfrac{3x^2+1}{x^2-4}$ функциясының асимптоталарын таңдаңыз (бірнеше жауап дұрыс).","o":["тік асимптота $x=2$","тік асимптота $x=-2$","көлденең асимптота $y=3$","көлбеу асимптота $y=x$"],"a":[0,1,2],"e":"Бөлгіш $x=\\pm2$-де нөл, алым нөл емес. Дәрежелер бірдей, көлденең асимптота $y=\\frac31=3$. Көлбеу асимптота жоқ (көлденең бар)."},{"id":"m1-3-pick:1","l":3,"lvl":"easy","type":"choice","ctx":"Асимптоталар мен түбірлер. Дұрыс жауапты таңдаңыз.","q":"$P(x)=-2x^4+x$ үшін $x\\to\\pm\\infty$ кезіндегі мінез қандай?","o":["екі жақта да $+\\infty$","екі жақта да $-\\infty$","солда $-\\infty$, оңда $+\\infty$","солда $+\\infty$, оңда $-\\infty$"],"a":1,"e":"Бас мүше $-2x^4$: дәреже жұп, коэффициент теріс - екі жақта да төмен."},{"id":"m1-3-pick:2","l":3,"lvl":"easy","type":"choice","ctx":"Асимптоталар мен түбірлер. Дұрыс жауапты таңдаңыз.","q":"$(x-1)^2(x+2)^3$ көпмүшелігінің графигі $x=-2$ нүктесінде $Ox$ осін...","o":["қиып өтеді","жанасады, бірақ қимайды","қиылыспайды","тік асимптота береді"],"a":0,"e":"Еселік 3 тақ, таңба ауысады, график осьті қиып өтеді (жатықтап). $x=1$ нүктесінде еселік жұп, сол жерде жанасады."},{"id":"m1-3-degree:0","l":3,"lvl":"easy","type":"num","ctx":"Дәрежені анықтау. Жауапты бүтін санмен жазыңыз.","q":"$(x^2+1)^3(x-2)$ көпмүшелігінің дәрежесі.","a":7},{"id":"m1-3-degree:1","l":3,"lvl":"easy","type":"num","ctx":"Дәрежені анықтау. Жауапты бүтін санмен жазыңыз.","q":"$P(x)=x^2+1$, $Q(x)=x^3-x$ болса, $\\deg\\,P(Q(x))$ неге тең?","a":6},{"id":"m1-3-domain:0","l":3,"lvl":"medium","type":"interval","ctx":"Рационал функцияның облысы. Облысты аралық түрінде жазыңыз (шексіздік - oo, бірігу - U).","q":"$f(x)=\\dfrac{x+1}{x^3-x}$","a":"(-oo; -1) U (-1; 0) U (0; 1) U (1; oo)"},{"id":"m1-3-domain:1","l":3,"lvl":"medium","type":"interval","ctx":"Рационал функцияның облысы. Облысты аралық түрінде жазыңыз (шексіздік - oo, бірігу - U).","q":"$g(x)=\\dfrac{1}{x^2+4}$","a":"R"},{"id":"m1-3-divide:0","l":3,"lvl":"medium","type":"expr","ctx":"Бөлінді. Бөлінді көпмүшелікті $x$ арқылы жазыңыз (қалдықсыз бөлінбесе де, тек бөлінді сұралады).","q":"$x^3-2x^2-5x+6$ көпмүшелігін $x-3$-ке бөлгендегі бөлінді.","a":"x^2+x-2"},{"id":"m1-3-divide:1","l":3,"lvl":"medium","type":"expr","ctx":"Бөлінді. Бөлінді көпмүшелікті $x$ арқылы жазыңыз (қалдықсыз бөлінбесе де, тек бөлінді сұралады).","q":"$x^3+2x^2-x+4$ көпмүшелігін $x+1$-ге бөлгендегі бөлінді.","a":"x^2+x-2"},{"id":"m1-3-coef:0","l":3,"lvl":"medium","type":"num","ctx":"Белгісіз коэффициент. Жауапты санмен жазыңыз.","q":"$x^3+kx^2-4x+4$ көпмүшелігі $x-2$-ге қалдықсыз бөлінеді. $k$ неге тең?","a":-1},{"id":"m1-3-coef:1","l":3,"lvl":"medium","type":"num","ctx":"Белгісіз коэффициент. Жауапты санмен жазыңыз.","q":"$x^3-6x^2+mx-6$ көпмүшелігінің бір түбірі $x=1$. $m$ неге тең?","a":11},{"id":"m1-3-horner:0","l":3,"lvl":"medium","type":"matrix","ctx":"Горнер схемасы. Нәтижелерді жол түрінде жазыңыз.","q":"$2x^3-3x^2-11x+6$ көпмүшелігін $x-3$-ке бөлгендегі бөлінді коэффициенттері.","orient":"row","name":"$[x^2,\\,x,\\,1]$:","a":[2,3,-2]},{"id":"m1-3-horner:1","l":3,"lvl":"medium","type":"matrix","ctx":"Горнер схемасы. Нәтижелерді жол түрінде жазыңыз.","q":"$x^3-2x^2+x-5$ көпмүшелігін $x-2$-ге бөлгенде Горнер жолы (соңғы сан - қалдық).","orient":"row","name":"Горнер жолы:","a":[1,0,1,-3]},{"id":"m1-3-rational:0","l":3,"lvl":"medium","type":"interval","ctx":"Рационал теңсіздік. Шешімді аралық түрінде жазыңыз.","q":"$\\dfrac{x^2-4}{x^2-1}&lt;0$","a":"(-2; -1) U (1; 2)"},{"id":"m1-3-rational:1","l":3,"lvl":"medium","type":"interval","ctx":"Рационал теңсіздік. Шешімді аралық түрінде жазыңыз.","q":"$\\dfrac{x+3}{x-1}\\ge0$","a":"(-oo; -3] U (1; oo)"},{"id":"m1-3-vieta3:0","l":3,"lvl":"medium","type":"num","ctx":"Үшінші дәрежелі теңдеу үшін Виет. Жауапты санмен жазыңыз.","q":"$x^3-4x^2+x+6=0$ теңдеуі түбірлерінің қосындысы.","a":4},{"id":"m1-3-vieta3:1","l":3,"lvl":"medium","type":"num","ctx":"Үшінші дәрежелі теңдеу үшін Виет. Жауапты санмен жазыңыз.","q":"Сол теңдеу түбірлерінің көбейтіндісі.","a":-6},{"id":"m1-3-vieta3:2","l":3,"lvl":"medium","type":"num","ctx":"Үшінші дәрежелі теңдеу үшін Виет. Жауапты санмен жазыңыз.","q":"Сол теңдеу түбірлерінің квадраттарының қосындысы.","a":14},{"id":"m1-3-slant:0","l":3,"lvl":"medium","type":"expr","ctx":"Көлбеу асимптота. Асимптотаның теңдеуін $y=\\dots$ емес, оң жағын ғана $x$ арқылы жазыңыз.","q":"$g(x)=\\dfrac{x^2+x-2}{x-3}$ функциясының көлбеу асимптотасы $y=\\ ?$","a":"x+4"},{"id":"m1-3-slant:1","l":3,"lvl":"medium","type":"expr","ctx":"Көлбеу асимптота. Асимптотаның теңдеуін $y=\\dots$ емес, оң жағын ғана $x$ арқылы жазыңыз.","q":"$h(x)=\\dfrac{2x^2-3x+1}{x+1}$ функциясының көлбеу асимптотасы $y=\\ ?$","a":"2*x-5"},{"id":"m1-3-cand:0","l":3,"lvl":"hard","type":"num","ctx":"Түбір үміткерлерінің саны. Жауапты бүтін санмен жазыңыз.","q":"$6x^3-13x^2+x+2$ көпмүшелігі үшін рационал түбірлер теоремасы берген әртүрлі $\\pm\\frac pq$ үміткерлер саны қанша?","a":12},{"id":"m1-3-cand:1","l":3,"lvl":"hard","type":"num","ctx":"Түбір үміткерлерінің саны. Жауапты бүтін санмен жазыңыз.","q":"Сол көпмүшенің ең үлкен түбірі.","a":2},{"id":"m1-3-polyineq:0","l":3,"lvl":"hard","type":"interval","ctx":"Көпмүшелік теңсіздік. Шешімді аралық түрінде жазыңыз.","q":"$x^4-x^3-7x^2+x+6\\ge0$","a":"(-oo; -2] U [-1; 1] U [3; oo)"},{"id":"m1-3-polyineq:1","l":3,"lvl":"hard","type":"interval","ctx":"Көпмүшелік теңсіздік. Шешімді аралық түрінде жазыңыз.","q":"$(x-1)^2(x+3)\\le0$","a":"(-oo; -3] U [1; 1]"},{"id":"m1-3-pfrac:0","l":3,"lvl":"hard","type":"matrix","ctx":"Қарапайым бөлшектер. $\\dfrac{5x+1}{(x-1)(x+2)}=\\dfrac{A}{x-1}+\\dfrac{B}{x+2}$ үшін $(A,\\,B)$ коэффициенттерін жазыңыз.","q":"$A$ мен $B$ мәндерін жол түрінде жазыңыз.","orient":"row","name":"$(A,\\,B)=$","a":[2,3]},{"id":"m1-3-pfrac:1","l":3,"lvl":"hard","type":"matrix","ctx":"Қарапайым бөлшектер. $\\dfrac{5x+1}{(x-1)(x+2)}=\\dfrac{A}{x-1}+\\dfrac{B}{x+2}$ үшін $(A,\\,B)$ коэффициенттерін жазыңыз.","q":"$\\dfrac{3x-1}{x(x-2)}=\\dfrac Cx+\\dfrac D{x-2}$ үшін $(C,\\,D)$.","orient":"row","name":"$(C,\\,D)=$","a":[0.5,2.5]},{"id":"m1-3-tf-hard:0","l":3,"lvl":"hard","type":"tf","ctx":"Асимптота мен түбір: түсіну. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"Рационал функция графигі өзінің көлденең асимптотасын қиып өте алады.","a":true,"e":"Ақиқат: $f(x)=\\frac{x}{x^2+1}$ үшін асимптота $y=0$, ал $f(0)=0$."},{"id":"m1-3-tf-hard:1","l":3,"lvl":"hard","type":"tf","ctx":"Асимптота мен түбір: түсіну. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"Бөлгіш нөлге айналатын әрбір нүктеде рационал функцияның тік асимптотасы болады.","a":false,"e":"Жалған: ортақ көбейткіш қысқарса, тесік қалады. Мысалы $\\frac{x^2-1}{x-1}$."},{"id":"m1-3-tf-hard:2","l":3,"lvl":"hard","type":"tf","ctx":"Асимптота мен түбір: түсіну. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"Нақты коэффициентті $x^3+px+q$ көпмүшелігі әрдайым дәл үш нақты түбірге ие.","a":false,"e":"Жалған: $x^3+x+1$ тек бір нақты түбірге ие (қалған екеуі комплекс)."},{"id":"m1-3-tf-hard:3","l":3,"lvl":"hard","type":"tf","ctx":"Асимптота мен түбір: түсіну. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"Егер $\\frac pq$ қысқармайтын бөлшек $x^2-2=0$ түбірі болса, онда $p\\mid2$ және $q\\mid1$.","a":true,"e":"Ақиқат, бірақ бұл үміткерлер ($\\pm1,\\pm2$) түбір бола алмайды: $\\sqrt2$ иррационал. Теорема түбірдің болуын кепілдемейді."},{"id":"w2-q0","l":3,"lvl":"quiz","type":"choice","q":"P(x) = x³ − 4x + 1 көпмүшелігін x − 2-ге бөлгендегі қалдық неге тең?","o":["−1","9","0","1"],"a":3,"e":"Безу теоремасы: қалдық P(2) = 8 − 8 + 1 = 1."},{"id":"w2-q1","l":3,"lvl":"quiz","type":"choice","q":"P(x) көпмүшелігі (x + 3)-ке қалдықсыз бөлінсе, не дұрыс?","o":["P(3) = 0","P(−3) = 0","P(0) = 3","P(x) = x + 3"],"a":1,"e":"x + 3 = x − (−3), сондықтан P(−3) = 0. Қалдық P(−3) нөл болуы керек."},{"id":"w2-q2","l":3,"lvl":"quiz","type":"choice","q":"3x² − 7x + 2 = 0 теңдеуінің түбірлері қайсы?","o":["1/3 және 2","−1/3 және −2","3 және 2","1/2 және 3"],"a":0,"e":"Үміткерлер ±1, ±2, ±1/3, ±2/3. D = 49 − 24 = 25, x = (7 ± 5)/6, яғни 2 және 1/3."},{"id":"w2-q3","l":3,"lvl":"quiz","type":"choice","q":"f(x) = (x² − 1)/(x − 1) функциясының графигі қандай?","o":["x = 1 тік асимптотасы бар","парабола","y = x + 1 түзуі, x = 1 нүктесі жоқ","y = x − 1 түзуі"],"a":2,"e":"x ≠ 1 үшін бөлшек x + 1-ге тең. x = 1 - тесік (ордината 2), тік асимптота емес."},{"id":"w2-q4","l":3,"lvl":"quiz","type":"choice","q":"f(x) = (4x² + 1)/(2x² − 3) функциясының көлденең асимптотасы қандай?","o":["y = 4","y = 2","y = 0","y = 1/3"],"a":1,"e":"Дәрежелері тең, бас коэффициенттер қатынасы 4/2 = 2."},{"id":"w2-q5","l":3,"lvl":"quiz","type":"choice","q":"g(x) = (x² + 3)/(x − 1) функциясының көлбеу асимптотасы қайсы?","o":["y = x","y = x − 1","y = x + 1","y = x + 4"],"a":2,"e":"x² + 3 = (x − 1)(x + 1) + 4, сондықтан g(x) = x + 1 + 4/(x − 1). Асимптота y = x + 1."},{"id":"w2-q6","l":3,"lvl":"quiz","type":"choice","q":"P(x) = −2x⁴ + x көпмүшелігі x → ±∞ кезінде қалай өзгереді?","o":["екі жақта да +∞","солда −∞, оңда +∞","солда +∞, оңда −∞","екі жақта да −∞"],"a":3,"e":"Бас мүше −2x⁴: дәреже жұп, коэффициент теріс. Екі жақта да мән −∞-ке ұмтылады."},{"id":"w2-q7","l":3,"lvl":"quiz","type":"choice","q":"Нақты коэффициентті 5-ші дәрежелі көпмүшеліктің нақты түбірлері туралы не дұрыс?","o":["кемі бір нақты түбірі бар","дәл бес нақты түбірі бар","нақты түбірі болмауы мүмкін","нақты түбірлері тек жұп болады"],"a":0,"e":"Тақ дәрежелі үзіліссіз көпмүшелік екі шетінде қарама-қарсы таңбалы мән қабылдайды, сондықтан осьті қияды. Саны 1, 3 немесе 5."},{"id":"m1-4-pow:0","l":4,"lvl":"easy","type":"num","ctx":"Дәреже мәндері. Жауапты санмен немесе бөлшекпен (мысалы, 1/8) жазыңыз.","q":"$2^{-3}$ неге тең?","a":"1/8"},{"id":"m1-4-pow:1","l":4,"lvl":"easy","type":"num","ctx":"Дәреже мәндері. Жауапты санмен немесе бөлшекпен (мысалы, 1/8) жазыңыз.","q":"$27^{2/3}$ неге тең?","a":9},{"id":"m1-4-pow:2","l":4,"lvl":"easy","type":"num","ctx":"Дәреже мәндері. Жауапты санмен немесе бөлшекпен (мысалы, 1/8) жазыңыз.","q":"$\\left(\\dfrac14\\right)^{-1/2}$ неге тең?","a":2},{"id":"m1-4-tf:0","l":4,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$\\log_2 8=3$.","a":true,"e":"Ақиқат: $2^3=8$."},{"id":"m1-4-tf:1","l":4,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$\\log(a+b)=\\log a+\\log b$ барлық оң $a$, $b$ үшін.","a":false,"e":"Жалған: логарифм көбейтіндіні қосындыға айналдырады. $\\log_2(4+4)=3\\ne4$."},{"id":"m1-4-tf:2","l":4,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$y=2^x$ функциясының мәндер жиыны барлық нақты сан.","a":false,"e":"Жалған: $2^x&gt;0$ әрдайым, мәндер жиыны $(0;+\\infty)$."},{"id":"m1-4-tf:3","l":4,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$y=\\left(\\frac13\\right)^x$ функциясы кемімелі.","a":true,"e":"Ақиқат: негіз $0&lt;a&lt;1$, сондықтан $x$ өскенде мәні азаяды."},{"id":"m1-4-tf:4","l":4,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$\\ln(-1)$ нақты сан ретінде анықталған.","a":false,"e":"Жалған: логарифм тек оң сан үшін анықталған."},{"id":"m1-4-pick:0","l":4,"lvl":"easy","type":"choice","ctx":"Қасиеттерді тану. Дұрыс жауапты таңдаңыз.","q":"$f(x)=\\ln(3-x)$ функциясының облысы қандай?","o":["$x&lt;3$","$x&gt;3$","$x\\ge3$","барлық нақты сан"],"a":0,"e":"Аргумент оң: $3-x&gt;0$, яғни $x&lt;3$."},{"id":"m1-4-pick:1","l":4,"lvl":"easy","type":"choice","ctx":"Қасиеттерді тану. Дұрыс жауапты таңдаңыз.","q":"Қай функциялар өспелі? Дұрыс жауаптардың барлығын белгілеңіз.","o":["$y=3^x$","$y=\\left(\\frac13\\right)^x$","$y=\\log_2x$","$y=\\log_{1/2}x$"],"a":[0,2],"e":"Негізі 1-ден үлкен болса, көрсеткіштік те, логарифмдік те функция өспелі."},{"id":"m1-4-pick:2","l":4,"lvl":"easy","type":"choice","ctx":"Қасиеттерді тану. Дұрыс жауапты таңдаңыз.","q":"$e^{\\ln5+\\ln2}$ неге тең?","o":["$7$","$10$","$e^7$","$\\ln10$"],"a":1,"e":"$\\ln5+\\ln2=\\ln10$, сондықтан $e^{\\ln10}=10$."},{"id":"m1-4-logs:0","l":4,"lvl":"easy","type":"num","ctx":"Логарифмдерді есептеу. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$\\log_381$","a":4},{"id":"m1-4-logs:1","l":4,"lvl":"easy","type":"num","ctx":"Логарифмдерді есептеу. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$\\log_2\\dfrac18$","a":-3},{"id":"m1-4-logs:2","l":4,"lvl":"easy","type":"num","ctx":"Логарифмдерді есептеу. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$\\lg4+\\lg25$","a":2},{"id":"m1-4-simplify:0","l":4,"lvl":"medium","type":"expr","ctx":"Логарифмдік өрнекті ықшамдау. Өрнекті $x$ арқылы жазыңыз ($x>0$). Натурал логарифм: ln(x), дәреже: x^2.","q":"$\\ln x^5-\\ln x^2$ өрнегін ықшамдаңыз.","a":"3*ln(x)","dom":[0.5,6]},{"id":"m1-4-simplify:1","l":4,"lvl":"medium","type":"expr","ctx":"Логарифмдік өрнекті ықшамдау. Өрнекті $x$ арқылы жазыңыз ($x>0$). Натурал логарифм: ln(x), дәреже: x^2.","q":"$e^{2\\ln x}$ өрнегін ықшамдаңыз.","a":"x^2","dom":[0.5,6]},{"id":"m1-4-domain:0","l":4,"lvl":"medium","type":"interval","ctx":"Логарифмдік функцияның облысы. Облысты аралық түрінде жазыңыз (шексіздік - oo, бірігу - U).","q":"$f(x)=\\ln(x^2-4)$","a":"(-oo; -2) U (2; oo)"},{"id":"m1-4-domain:1","l":4,"lvl":"medium","type":"interval","ctx":"Логарифмдік функцияның облысы. Облысты аралық түрінде жазыңыз (шексіздік - oo, бірігу - U).","q":"$g(x)=\\log_2\\dfrac{x-1}{x+3}$","a":"(-oo; -3) U (1; oo)"},{"id":"m1-4-expeq:0","l":4,"lvl":"medium","type":"num","ctx":"Көрсеткіштік теңдеулер. Жауапты санмен жазыңыз.","q":"$4^x-5\\cdot2^x+4=0$ теңдеуі түбірлерінің қосындысы.","a":2},{"id":"m1-4-expeq:1","l":4,"lvl":"medium","type":"num","ctx":"Көрсеткіштік теңдеулер. Жауапты санмен жазыңыз.","q":"$9^x=27^{x-2}$ теңдеуінің шешімі.","a":6},{"id":"m1-4-expineq:0","l":4,"lvl":"medium","type":"interval","ctx":"Көрсеткіштік теңсіздіктер. Шешімді аралық түрінде жазыңыз.","q":"$\\left(\\dfrac12\\right)^{x^2-x}\\ge\\dfrac14$","a":"[-1; 2]"},{"id":"m1-4-expineq:1","l":4,"lvl":"medium","type":"interval","ctx":"Көрсеткіштік теңсіздіктер. Шешімді аралық түрінде жазыңыз.","q":"$3^{2x-1}&lt;27$","a":"(-oo; 2)"},{"id":"m1-4-logeq:0","l":4,"lvl":"medium","type":"num","ctx":"Логарифмдік теңдеулер. Облысты тексеріп, жауапты санмен жазыңыз.","q":"$\\log_2(x+3)+\\log_2(x-3)=4$ теңдеуінің шешімі.","a":5},{"id":"m1-4-logeq:1","l":4,"lvl":"medium","type":"num","ctx":"Логарифмдік теңдеулер. Облысты тексеріп, жауапты санмен жазыңыз.","q":"$\\log_3(2x-1)=2$ теңдеуінің шешімі.","a":5},{"id":"m1-4-table:0","l":4,"lvl":"medium","type":"matrix","ctx":"Кесте мен логарифм мәндері. Мәндерді жол түрінде жазыңыз.","q":"$y=2^x$ функциясының $x=-2,-1,0,1,2$ нүктелеріндегі мәндері.","orient":"row","name":"$2^x$:","a":[0.25,0.5,1,2,4]},{"id":"m1-4-table:1","l":4,"lvl":"medium","type":"matrix","ctx":"Кесте мен логарифм мәндері. Мәндерді жол түрінде жазыңыз.","q":"$\\log_2 1,\\ \\log_22,\\ \\log_24,\\ \\log_28$ мәндері.","orient":"row","name":"$\\log_2$:","a":[0,1,2,3]},{"id":"m1-4-inv:0","l":4,"lvl":"medium","type":"expr","ctx":"Кері функция. Өрнекті $x$ арқылы жазыңыз.","q":"$f(x)=2e^x+1$ функциясының кері функциясы $f^{-1}(x)=\\ ?$","a":"ln((x-1)/2)","dom":[1.5,8]},{"id":"m1-4-change:0","l":4,"lvl":"hard","type":"num","ctx":"Негізді ауыстыру. Жауапты санмен жазыңыз.","q":"$\\log_23\\cdot\\log_35\\cdot\\log_58$ мәні.","a":3},{"id":"m1-4-change:1","l":4,"lvl":"hard","type":"num","ctx":"Негізді ауыстыру. Жауапты санмен жазыңыз.","q":"$9^{\\log_35}$ мәні.","a":25},{"id":"m1-4-change:2","l":4,"lvl":"hard","type":"num","ctx":"Негізді ауыстыру. Жауапты санмен жазыңыз.","q":"$\\log_{1/2}16$ мәні.","a":-4},{"id":"m1-4-cont:0","l":4,"lvl":"hard","type":"num","ctx":"Үздіксіз өсу. Жауапты санмен жазыңыз (жуықтау қателігі рұқсат етіледі).","q":"Сома жылдық 8% үздіксіз өседі: $A=Pe^{0{,}08t}$. Сома үш есе болу үшін қанша жыл керек? (0,01-ге дейін, жылмен)","a":"ln(3)/0.08","tol":0.01,"round":"0,01-ге дейін","unit":"жыл"},{"id":"m1-4-cont:1","l":4,"lvl":"hard","type":"num","ctx":"Үздіксіз өсу. Жауапты санмен жазыңыз (жуықтау қателігі рұқсат етіледі).","q":"Сома жылына 12 рет қосылатын 12% мөлшерлемемен $P(1+0{,}01)^{12t}$ түрінде өседі. $t=1$ жылдан кейінгі өсу коэффициентін табыңыз (0,0001-ге дейін).","a":"1.01^12","tol":0.0001},{"id":"m1-4-loginq:0","l":4,"lvl":"hard","type":"interval","ctx":"Логарифмдік теңсіздіктер. Шешімді аралық түрінде жазыңыз.","q":"$\\log_2(x^2-3x)\\le2$","a":"[-1; 0) U (3; 4]"},{"id":"m1-4-loginq:1","l":4,"lvl":"hard","type":"interval","ctx":"Логарифмдік теңсіздіктер. Шешімді аралық түрінде жазыңыз.","q":"$\\log_{1/2}(x-1)&gt;-2$","a":"(1; 5)"},{"id":"m1-4-tf-hard:0","l":4,"lvl":"hard","type":"tf","ctx":"Түсіну: логарифм мен дәреже. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$\\ln x^2=2\\ln x$ барлық $x\\ne0$ үшін.","a":false,"e":"Жалған: теріс $x$ үшін $\\ln x$ анықталмаған. Дұрысы: $\\ln x^2=2\\ln|x|$."},{"id":"m1-4-tf-hard:1","l":4,"lvl":"hard","type":"tf","ctx":"Түсіну: логарифм мен дәреже. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$\\log_ab\\cdot\\log_ba=1$ (барлық рұқсат етілген $a,b$ үшін).","a":true,"e":"Ақиқат: негізді ауыстыру формуласынан $\\frac{\\ln b}{\\ln a}\\cdot\\frac{\\ln a}{\\ln b}=1$ ($a,b\\ne1$)."},{"id":"m1-4-tf-hard:2","l":4,"lvl":"hard","type":"tf","ctx":"Түсіну: логарифм мен дәреже. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$\\left(1+\\frac1n\\right)^n$ тізбегі $n$ өскенде кемиді.","a":false,"e":"Жалған: тізбек өспелі ($2;\\,2{,}25;\\,2{,}37;\\,\\dots$) және $e$-ге жақындайды."},{"id":"m1-4-tf-hard:3","l":4,"lvl":"hard","type":"tf","ctx":"Түсіну: логарифм мен дәреже. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"Егер $A=Pe^{rt}$, $r&gt;0$ болса, екі еселену уақыты $T=\\dfrac{\\ln2}{r}$.","a":true,"e":"Ақиқат: $e^{rT}=2\\Rightarrow rT=\\ln2$."},{"id":"w3-q0","l":4,"lvl":"quiz","type":"choice","q":"log₂ 32 неге тең?","o":["4","6","16","5"],"a":3,"e":"2⁵ = 32, сондықтан log₂ 32 = 5."},{"id":"w3-q1","l":4,"lvl":"quiz","type":"choice","q":"f(x) = ln(3 − x) функциясының анықталу облысы қандай?","o":["x > 3","x < 3","x ≥ 3","барлық нақты сан"],"a":1,"e":"Логарифмнің аргументі оң болуы керек: 3 − x > 0, яғни x < 3."},{"id":"w3-q2","l":4,"lvl":"quiz","type":"choice","q":"lg 4 + lg 25 неге тең?","o":["2","29","100","lg 29"],"a":0,"e":"Көбейтінді қасиеті бойынша lg 4 + lg 25 = lg 100 = 2."},{"id":"w3-q3","l":4,"lvl":"quiz","type":"choice","q":"2ˣ = 1/8 теңдеуінің шешімі қайсы?","o":["3","−3","1/3","−1/3"],"a":1,"e":"1/8 = 2⁻³, демек x = −3."},{"id":"w3-q4","l":4,"lvl":"quiz","type":"choice","q":"e^(ln 5 + ln 2) неге тең?","o":["7","e⁷","10","ln 10"],"a":2,"e":"ln 5 + ln 2 = ln 10, сондықтан e^(ln 10) = 10."},{"id":"w3-q5","l":4,"lvl":"quiz","type":"choice","q":"log₉ 27 неге тең?","o":["3","2/3","3/2","1/3"],"a":2,"e":"Негізді ауыстырамыз: log₉ 27 = log₃ 27/log₃ 9 = 3/2. Тексеру: 9^(3/2) = 27."},{"id":"w3-q6","l":4,"lvl":"quiz","type":"choice","q":"(1/3)ˣ > 9 теңсіздігінің шешімі қайсы?","o":["x > −2","x < 2","x > 2","x < −2"],"a":3,"e":"9 = (1/3)⁻². Негіз 1-ден кіші, сондықтан таңба өзгереді: x < −2."},{"id":"w3-q7","l":4,"lvl":"quiz","type":"choice","q":"Бактерия саны әр 4 сағатта екі есе өседі. Басында 100 болса, 12 сағаттан кейін қанша болады?","o":["300","600","800","1200"],"a":2,"e":"12/4 = 3 екі еселену: 100 · 2³ = 800."},{"id":"m1-5-convert:0","l":5,"lvl":"easy","type":"num","ctx":"Градус пен радиан. Жауапты санмен жазыңыз ($\\pi$ үшін pi, мысалы pi/2).","q":"$90^\\circ$ бұрышты радианмен жазыңыз.","a":"pi/2"},{"id":"m1-5-convert:1","l":5,"lvl":"easy","type":"num","ctx":"Градус пен радиан. Жауапты санмен жазыңыз ($\\pi$ үшін pi, мысалы pi/2).","q":"$\\dfrac{5\\pi}{6}$ радианды градуспен жазыңыз.","a":150},{"id":"m1-5-convert:2","l":5,"lvl":"easy","type":"num","ctx":"Градус пен радиан. Жауапты санмен жазыңыз ($\\pi$ үшін pi, мысалы pi/2).","q":"$-\\dfrac{\\pi}{3}$ радианды градуспен жазыңыз.","a":-60},{"id":"m1-5-tf:0","l":5,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$180^\\circ=\\pi$ радиан.","a":true,"e":"Ақиқат: жарты шеңбердің ұзындығы $\\pi r$, радиус $r$-ге бөлсек $\\pi$."},{"id":"m1-5-tf:1","l":5,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$\\sin\\theta=\\dfrac32$ болатын нақты $\\theta$ бар.","a":false,"e":"Жалған: синус бірлік шеңбердегі нүктенің ординатасы, ол $-1$ мен $1$ аралығында."},{"id":"m1-5-tf:2","l":5,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$\\cos(-\\theta)=\\cos\\theta$.","a":true,"e":"Ақиқат: $-\\theta$ нүктесі $P(\\theta)$-ның $Ox$ осіне қатысты шағылысы, абсцисса сақталады."},{"id":"m1-5-tf:3","l":5,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$\\tan\\dfrac{\\pi}{2}=0$.","a":false,"e":"Жалған: $\\cos\\frac{\\pi}{2}=0$, тангенс анықталмаған."},{"id":"m1-5-tf:4","l":5,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"III ширекте синус та, косинус та теріс.","a":true,"e":"Ақиқат: III ширекте $x<0$ және $y<0$. Сондықтан тангенс оң."},{"id":"m1-5-pick:0","l":5,"lvl":"easy","type":"choice","ctx":"Ширектер мен таңбалар. Дұрыс жауапты таңдаңыз.","q":"Қай өрнектер оң? Дұрыс жауаптардың барлығын белгілеңіз.","o":["$\\cos150^\\circ$","$\\sin210^\\circ$","$\\tan225^\\circ$","$\\cos300^\\circ$"],"a":[2,3],"e":"$150^\\circ$ - II ширек, косинус теріс. $210^\\circ$ - III ширек, синус теріс. $225^\\circ$ - III ширек, тангенс оң. $300^\\circ$ - IV ширек, косинус оң."},{"id":"m1-5-pick:1","l":5,"lvl":"easy","type":"choice","ctx":"Ширектер мен таңбалар. Дұрыс жауапты таңдаңыз.","q":"$\\sin\\theta>0$ және $\\cos\\theta<0$ болса, $\\theta$ қай ширекте?","o":["I ширек","II ширек","III ширек","IV ширек"],"a":1,"e":"Ордината оң, абсцисса теріс: нүкте жоғарғы сол жақта, яғни II ширек."},{"id":"m1-5-pick:2","l":5,"lvl":"easy","type":"choice","ctx":"Ширектер мен таңбалар. Дұрыс жауапты таңдаңыз.","q":"$\\sin(x+\\pi)$ неге тең?","o":["$\\sin x$","$-\\sin x$","$\\cos x$","$-\\cos x$"],"a":1,"e":"$\\pi$ бұрылыс нүктені координата басына қатысты симметриялы орынға көшіреді, ордината таңбасы ауысады."},{"id":"m1-5-special:0","l":5,"lvl":"easy","type":"num","ctx":"Арнайы мәндер. Жауапты санмен немесе өрнекпен (мысалы, sqrt(3)/2) жазыңыз.","q":"$\\sin30^\\circ+\\cos60^\\circ$","a":1},{"id":"m1-5-special:1","l":5,"lvl":"easy","type":"num","ctx":"Арнайы мәндер. Жауапты санмен немесе өрнекпен (мысалы, sqrt(3)/2) жазыңыз.","q":"$\\tan45^\\circ$","a":1},{"id":"m1-5-special:2","l":5,"lvl":"easy","type":"num","ctx":"Арнайы мәндер. Жауапты санмен немесе өрнекпен (мысалы, sqrt(3)/2) жазыңыз.","q":"$\\cos\\pi$","a":-1},{"id":"m1-5-identity:0","l":5,"lvl":"medium","type":"expr","ctx":"Тепе-теңдіктермен ықшамдау. Өрнекті $x$ арқылы жазыңыз (функциялар: sin(x), cos(x), дәреже: sin(x)^2).","q":"$\\dfrac{\\sin^2x}{1-\\cos x}$ өрнегін ықшамдаңыз.","a":"1+cos(x)","dom":[0.2,3]},{"id":"m1-5-identity:1","l":5,"lvl":"medium","type":"expr","ctx":"Тепе-теңдіктермен ықшамдау. Өрнекті $x$ арқылы жазыңыз (функциялар: sin(x), cos(x), дәреже: sin(x)^2).","q":"$(1-\\sin^2x)\\tan^2x$ өрнегін ықшамдаңыз.","a":"sin(x)^2","dom":[0.2,1.3]},{"id":"m1-5-identity:2","l":5,"lvl":"medium","type":"expr","ctx":"Тепе-теңдіктермен ықшамдау. Өрнекті $x$ арқылы жазыңыз (функциялар: sin(x), cos(x), дәреже: sin(x)^2).","q":"$\\sin(\\pi-x)+\\cos\\left(\\dfrac{\\pi}{2}-x\\right)$ өрнегін ықшамдаңыз.","a":"2*sin(x)"},{"id":"m1-5-exact:0","l":5,"lvl":"medium","type":"num","ctx":"Дәл мәндер. Жауапты санмен немесе өрнекпен (мысалы, -sqrt(3)/2) жазыңыз.","q":"$\\sin\\dfrac{5\\pi}{6}$","a":"1/2"},{"id":"m1-5-exact:1","l":5,"lvl":"medium","type":"num","ctx":"Дәл мәндер. Жауапты санмен немесе өрнекпен (мысалы, -sqrt(3)/2) жазыңыз.","q":"$\\cos\\dfrac{7\\pi}{6}$","a":"-sqrt(3)/2"},{"id":"m1-5-exact:2","l":5,"lvl":"medium","type":"num","ctx":"Дәл мәндер. Жауапты санмен немесе өрнекпен (мысалы, -sqrt(3)/2) жазыңыз.","q":"$\\sin\\dfrac{11\\pi}{4}$","a":"sqrt(2)/2"},{"id":"m1-5-fromone:0","l":5,"lvl":"medium","type":"num","ctx":"Бір функциядан қалғанын табу. Жауапты бөлшекпен жазыңыз (мысалы, -3/4).","q":"$\\sin\\theta=\\dfrac35$, $\\theta$ - II ширек. $\\cos\\theta=\\ ?$","a":"-4/5"},{"id":"m1-5-fromone:1","l":5,"lvl":"medium","type":"num","ctx":"Бір функциядан қалғанын табу. Жауапты бөлшекпен жазыңыз (мысалы, -3/4).","q":"Сол $\\theta$ үшін $\\tan\\theta=\\ ?$","a":"-3/4"},{"id":"m1-5-fromone:2","l":5,"lvl":"medium","type":"num","ctx":"Бір функциядан қалғанын табу. Жауапты бөлшекпен жазыңыз (мысалы, -3/4).","q":"$\\cos\\theta=\\dfrac{5}{13}$, $\\theta$ - IV ширек. $\\sin\\theta=\\ ?$","a":"-12/13"},{"id":"m1-5-coords:0","l":5,"lvl":"medium","type":"matrix","ctx":"Бірлік шеңбердегі нүкте. Нүктенің координаталарын жол түрінде жазыңыз (мысалы, -1/2 ; sqrt(3)/2).","q":"$\\theta=\\dfrac{2\\pi}{3}$ бұрышқа сәйкес бірлік шеңбердегі $(\\cos\\theta;\\sin\\theta)$ нүктесі.","orient":"row","name":"$P=$","a":["-1/2","sqrt(3)/2"]},{"id":"m1-5-coords:1","l":5,"lvl":"medium","type":"matrix","ctx":"Бірлік шеңбердегі нүкте. Нүктенің координаталарын жол түрінде жазыңыз (мысалы, -1/2 ; sqrt(3)/2).","q":"$\\theta=\\dfrac{5\\pi}{4}$ үшін $P=(\\cos\\theta;\\sin\\theta)$.","orient":"row","name":"$P=$","a":["-sqrt(2)/2","-sqrt(2)/2"]},{"id":"m1-5-ineq:0","l":5,"lvl":"medium","type":"interval","ctx":"Тригонометриялық теңсіздік. Шешімді $[0;\\,2\\pi)$ жартылай аралығында аралық түрінде жазыңыз ($\\pi$ үшін pi, мысалы (pi/6; 5*pi/6)).","q":"$\\sin x\\ge0$, $x\\in[0;2\\pi)$","a":"[0; pi]"},{"id":"m1-5-ineq:1","l":5,"lvl":"medium","type":"interval","ctx":"Тригонометриялық теңсіздік. Шешімді $[0;\\,2\\pi)$ жартылай аралығында аралық түрінде жазыңыз ($\\pi$ үшін pi, мысалы (pi/6; 5*pi/6)).","q":"$\\cos x&lt;0$, $x\\in[0;2\\pi)$","a":"(pi/2; 3*pi/2)"},{"id":"m1-5-reduce:0","l":5,"lvl":"medium","type":"choice","ctx":"Келтіру формулаларын тану. Дұрыс жауапты таңдаңыз.","q":"Қай өрнектер $\\sin x$-ке тепе-тең? Дұрыс жауаптардың барлығын белгілеңіз.","o":["$\\sin(\\pi-x)$","$\\cos\\left(\\frac{\\pi}{2}-x\\right)$","$-\\sin(-x)$","$\\sin(x+\\pi)$"],"a":[0,1,2],"e":"$\\sin(\\pi-x)=\\sin x$; $\\cos(\\frac{\\pi}{2}-x)=\\sin x$; $\\sin(-x)=-\\sin x$, сондықтан $-\\sin(-x)=\\sin x$. Ал $\\sin(x+\\pi)=-\\sin x$."},{"id":"m1-5-reduce:1","l":5,"lvl":"medium","type":"choice","ctx":"Келтіру формулаларын тану. Дұрыс жауапты таңдаңыз.","q":"$\\cos\\left(\\dfrac{\\pi}{2}+x\\right)$ неге тең?","o":["$\\sin x$","$-\\sin x$","$\\cos x$","$-\\cos x$"],"a":1,"e":"90° бұрыс $(x;y)\\to(-y;x)$: косинус $=-\\sin x$."},{"id":"m1-5-triangle:0","l":5,"lvl":"hard","type":"num","ctx":"Үшбұрышты шешу. Жауапты санмен немесе өрнекпен жазыңыз.","q":"$a=7$, $b=5$, $C=60^\\circ$ үшбұрыш. $c^2=\\ ?$","a":39},{"id":"m1-5-triangle:1","l":5,"lvl":"hard","type":"num","ctx":"Үшбұрышты шешу. Жауапты санмен немесе өрнекпен жазыңыз.","q":"Сол үшбұрыштың ауданы ($\\frac12ab\\sin C$). Нақты мәнін жазыңыз.","a":"35*sqrt(3)/4"},{"id":"m1-5-triangle:2","l":5,"lvl":"hard","type":"num","ctx":"Үшбұрышты шешу. Жауапты санмен немесе өрнекпен жазыңыз.","q":"Қабырғалары $3$, $4$, $5$ үшбұрыштың ең үлкен бұрышының косинусы.","a":0},{"id":"m1-5-count:0","l":5,"lvl":"hard","type":"num","ctx":"Теңдеу шешімдерінің саны. Жауапты бүтін санмен жазыңыз.","q":"$\\tan x=1$ теңдеуінің $[0;\\,4\\pi]$ кесіндісіндегі шешімдері неше?","a":4},{"id":"m1-5-count:1","l":5,"lvl":"hard","type":"num","ctx":"Теңдеу шешімдерінің саны. Жауапты бүтін санмен жазыңыз.","q":"$\\sin x=\\dfrac13$ теңдеуінің $[0;\\,2\\pi]$ кесіндісіндегі шешімдері неше?","a":2},{"id":"m1-5-tf-hard:0","l":5,"lvl":"hard","type":"tf","ctx":"Түсіну: бұрыш пен функция. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$\\sin2\\theta=2\\sin\\theta$ барлық $\\theta$ үшін.","a":false,"e":"Жалған: $\\theta=\\frac{\\pi}{2}$ үшін $\\sin\\pi=0$, ал $2\\sin\\frac{\\pi}{2}=2$."},{"id":"m1-5-tf-hard:1","l":5,"lvl":"hard","type":"tf","ctx":"Түсіну: бұрыш пен функция. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"Егер $\\cos\\alpha=\\cos\\beta$ болса, онда $\\alpha=\\beta$.","a":false,"e":"Жалған: $\\cos\\frac{\\pi}{3}=\\cos\\left(-\\frac{\\pi}{3}\\right)=\\frac12$, косинус бірмәнді емес."},{"id":"m1-5-tf-hard:2","l":5,"lvl":"hard","type":"tf","ctx":"Түсіну: бұрыш пен функция. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"Тікбұрышты үшбұрышта $\\sin\\alpha=\\cos(90^\\circ-\\alpha)$.","a":true,"e":"Ақиқат: бір сүйір бұрыштың қарсы катеті екіншісінің жанындағы катеті."},{"id":"m1-5-tf-hard:3","l":5,"lvl":"hard","type":"tf","ctx":"Түсіну: бұрыш пен функция. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"Косинустар теоремасы $C=90^\\circ$ кезінде Пифагор теоремасына айналады.","a":true,"e":"Ақиқат: $\\cos90^\\circ=0$, $c^2=a^2+b^2$."},{"id":"w4-q0","l":5,"lvl":"quiz","type":"choice","q":"150° бұрыштың радиандық өлшемі қандай?","o":["π/6","2π/3","3π/4","5π/6"],"a":3,"e":"150 · π/180 = 5π/6."},{"id":"w4-q1","l":5,"lvl":"quiz","type":"choice","q":"cos 120° неге тең?","o":["−1/2","1/2","−√3/2","√3/2"],"a":0,"e":"120° = 180° − 60°, II ширек: cos 120° = −cos 60° = −1/2."},{"id":"w4-q2","l":5,"lvl":"quiz","type":"choice","q":"Қай бұрышта tg θ анықталмаған?","o":["θ = 0","θ = π/2","θ = π","θ = π/4"],"a":1,"e":"cos(π/2) = 0, tg θ = sin θ / cos θ нөлге бөлінеді."},{"id":"w4-q3","l":5,"lvl":"quiz","type":"choice","q":"sin θ = 0,6 болса, cos² θ неге тең?","o":["0,4","0,8","0,64","0,36"],"a":2,"e":"cos² θ = 1 − sin² θ = 1 − 0,36 = 0,64."},{"id":"w4-q4","l":5,"lvl":"quiz","type":"choice","q":"Радиусы 6 шеңбердің π/3 радиан бұрышқа сәйкес доғасының ұзындығы қандай?","o":["2π","π/3","6π","18"],"a":0,"e":"l = rθ = 6 · π/3 = 2π."},{"id":"w4-q5","l":5,"lvl":"quiz","type":"choice","q":"sin θ > 0 және cos θ < 0 болса, θ қай ширекте?","o":["I","III","IV","II"],"a":3,"e":"Ордината оң, абсцисса теріс - жоғарғы сол жақ, яғни II ширек."},{"id":"w4-q6","l":5,"lvl":"quiz","type":"choice","q":"sin(π + x) неге тең?","o":["sin x","cos x","−sin x","−cos x"],"a":2,"e":"π бұрылыс нүктені координата басына қатысты симметриялы орынға көшіреді: sin(π + x) = −sin x."},{"id":"w4-q7","l":5,"lvl":"quiz","type":"choice","q":"cos(−π/3) неге тең?","o":["−1/2","1/2","√3/2","−√3/2"],"a":1,"e":"Косинус жұп: cos(−π/3) = cos(π/3) = 1/2."},{"id":"m1-6-period:0","l":6,"lvl":"easy","type":"num","ctx":"Амплитуда және период. Жауапты санмен немесе $\\pi$ арқылы (мысалы, 2*pi/3) жазыңыз.","q":"$y=3\\sin x-2$ функциясының амплитудасы.","a":3},{"id":"m1-6-period:1","l":6,"lvl":"easy","type":"num","ctx":"Амплитуда және период. Жауапты санмен немесе $\\pi$ арқылы (мысалы, 2*pi/3) жазыңыз.","q":"$y=\\sin2x$ функциясының негізгі периоды.","a":"pi"},{"id":"m1-6-period:2","l":6,"lvl":"easy","type":"num","ctx":"Амплитуда және период. Жауапты санмен немесе $\\pi$ арқылы (мысалы, 2*pi/3) жазыңыз.","q":"$y=\\cos\\dfrac x3$ функциясының негізгі периоды.","a":"6*pi"},{"id":"m1-6-tf:0","l":6,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$\\tan x$ функциясының негізгі периоды $2\\pi$.","a":false,"e":"Жалған: $\\tan(x+\\pi)=\\tan x$, негізгі период $\\pi$."},{"id":"m1-6-tf:1","l":6,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$\\arcsin x$ функциясының мәндер жиыны $\\left[-\\frac{\\pi}{2};\\frac{\\pi}{2}\\right]$.","a":true,"e":"Ақиқат: синусты осы аралыққа шектеп, бірмәнді етеміз."},{"id":"m1-6-tf:2","l":6,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$\\sin2x=2\\sin x$.","a":false,"e":"Жалған: $\\sin2x=2\\sin x\\cos x$. $x=\\frac{\\pi}{2}$ үшін $0\\ne2$."},{"id":"m1-6-tf:3","l":6,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$\\cos2x=1-2\\sin^2x$.","a":true,"e":"Ақиқат: $\\cos^2x-\\sin^2x$ ішіндегі $\\cos^2x=1-\\sin^2x$ қойылған."},{"id":"m1-6-tf:4","l":6,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$\\sin x=2$ теңдеуінің шешімі бар.","a":false,"e":"Жалған: $|\\sin x|\\le1$."},{"id":"m1-6-pick:0","l":6,"lvl":"easy","type":"choice","ctx":"Кері функциялар мен мәндер. Дұрыс жауапты таңдаңыз.","q":"$\\arcsin\\dfrac12$ неге тең?","o":["$\\dfrac{\\pi}{6}$","$\\dfrac{\\pi}{3}$","$\\dfrac{5\\pi}{6}$","$\\dfrac{\\pi}{4}$"],"a":0,"e":"$\\sin\\frac{\\pi}{6}=\\frac12$ және $\\frac{\\pi}{6}\\in\\left[-\\frac{\\pi}{2};\\frac{\\pi}{2}\\right]$."},{"id":"m1-6-pick:1","l":6,"lvl":"easy","type":"choice","ctx":"Кері функциялар мен мәндер. Дұрыс жауапты таңдаңыз.","q":"$\\arccos(-1)$ неге тең?","o":["$0$","$-\\dfrac{\\pi}{2}$","$\\pi$","$\\dfrac{\\pi}{2}$"],"a":2,"e":"$\\cos\\pi=-1$, $\\pi\\in[0;\\pi]$."},{"id":"m1-6-pick:2","l":6,"lvl":"easy","type":"choice","ctx":"Кері функциялар мен мәндер. Дұрыс жауапты таңдаңыз.","q":"Қай өрнектер мағыналы (нақты сан береді)? Дұрыс жауаптардың барлығын белгілеңіз.","o":["$\\arcsin2$","$\\arctan100$","$\\arccos0{,}3$","$\\arcsin(-1{,}2)$"],"a":[1,2],"e":"$\\arcsin$ мен $\\arccos$ тек $[-1;1]$ кесіндісінде анықталған, ал $\\arctan$ кез келген нақты санда."},{"id":"m1-6-addition:0","l":6,"lvl":"easy","type":"num","ctx":"Қосу формулалары. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$\\sin15^\\circ\\cos15^\\circ$ неге тең?","a":"1/4"},{"id":"m1-6-addition:1","l":6,"lvl":"easy","type":"num","ctx":"Қосу формулалары. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$\\cos^215^\\circ-\\sin^215^\\circ$ неге тең? (нақты мәнін жазыңыз, мысалы sqrt(3)/2)","a":"sqrt(3)/2"},{"id":"m1-6-addition:2","l":6,"lvl":"easy","type":"num","ctx":"Қосу формулалары. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$\\sin40^\\circ\\cos20^\\circ+\\cos40^\\circ\\sin20^\\circ$ неге тең?","a":"sqrt(3)/2"},{"id":"m1-6-identity:0","l":6,"lvl":"medium","type":"expr","ctx":"Формулалармен түрлендіру. Өрнекті $x$ арқылы жазыңыз (sin(x), cos(2x), tan(x), дәреже: sin(x)^2).","q":"$\\dfrac{1-\\cos2x}{2}$ өрнегін $\\sin x$ арқылы жазыңыз.","a":"sin(x)^2"},{"id":"m1-6-identity:1","l":6,"lvl":"medium","type":"expr","ctx":"Формулалармен түрлендіру. Өрнекті $x$ арқылы жазыңыз (sin(x), cos(2x), tan(x), дәреже: sin(x)^2).","q":"$\\cos4x$ өрнегін $\\cos2x$ арқылы жазыңыз.","a":"2*cos(2*x)^2-1"},{"id":"m1-6-identity:2","l":6,"lvl":"medium","type":"expr","ctx":"Формулалармен түрлендіру. Өрнекті $x$ арқылы жазыңыз (sin(x), cos(2x), tan(x), дәреже: sin(x)^2).","q":"$\\tan2x$ өрнегін $\\tan x$ арқылы жазыңыз.","a":"2*tan(x)/(1-tan(x)^2)","dom":[0.1,0.7]},{"id":"m1-6-exact:0","l":6,"lvl":"medium","type":"num","ctx":"Дәл мәндер. Жауапты өрнекпен жазыңыз (мысалы, (sqrt(6)+sqrt(2))/4).","q":"$\\sin75^\\circ$","a":"(sqrt(6)+sqrt(2))/4"},{"id":"m1-6-exact:1","l":6,"lvl":"medium","type":"num","ctx":"Дәл мәндер. Жауапты өрнекпен жазыңыз (мысалы, (sqrt(6)+sqrt(2))/4).","q":"$\\tan15^\\circ$","a":"2-sqrt(3)"},{"id":"m1-6-sumangle:0","l":6,"lvl":"medium","type":"num","ctx":"Қосындының косинусы. Жауапты бөлшекпен жазыңыз.","q":"$\\sin\\alpha=\\dfrac35$ ($\\alpha$ - I ширек), $\\cos\\beta=-\\dfrac5{13}$ ($\\beta$ - II ширек). $\\cos(\\alpha+\\beta)=\\ ?$","a":"-56/65"},{"id":"m1-6-sumangle:1","l":6,"lvl":"medium","type":"num","ctx":"Қосындының косинусы. Жауапты бөлшекпен жазыңыз.","q":"Сол үшін $\\sin(\\alpha+\\beta)=\\ ?$","a":"33/65"},{"id":"m1-6-trigineq:0","l":6,"lvl":"medium","type":"interval","ctx":"Тригонометриялық теңсіздік. Шешімді көрсетілген аралықта жазыңыз ($\\pi$ үшін pi).","q":"$\\sin x>\\dfrac12$, $x\\in[0;2\\pi)$","a":"(pi/6; 5*pi/6)"},{"id":"m1-6-trigineq:1","l":6,"lvl":"medium","type":"interval","ctx":"Тригонометриялық теңсіздік. Шешімді көрсетілген аралықта жазыңыз ($\\pi$ үшін pi).","q":"$\\cos2x\\ge0$, $x\\in[0;\\pi)$","a":"[0; pi/4] U [3*pi/4; pi)"},{"id":"m1-6-auxiliary:0","l":6,"lvl":"medium","type":"num","ctx":"Көмекші бұрыш: ең үлкен және ең кіші мән. Жауапты санмен немесе өрнекпен (мысалы, -2*sqrt(2)) жазыңыз.","q":"$3\\sin x+4\\cos x$ өрнегінің ең үлкен мәні.","a":5},{"id":"m1-6-auxiliary:1","l":6,"lvl":"medium","type":"num","ctx":"Көмекші бұрыш: ең үлкен және ең кіші мән. Жауапты санмен немесе өрнекпен (мысалы, -2*sqrt(2)) жазыңыз.","q":"$2\\sin x-2\\cos x$ өрнегінің ең кіші мәні.","a":"-2*sqrt(2)"},{"id":"m1-6-sumprod:0","l":6,"lvl":"hard","type":"expr","ctx":"Қосындыны көбейтіндіге айналдыру. Өрнекті $x$ арқылы жазыңыз.","q":"$\\sin x+\\sin3x$ қосындысын көбейтінді түрінде жазыңыз ($\\sin2x$ пен $\\cos x$ арқылы).","a":"2*sin(2*x)*cos(x)"},{"id":"m1-6-count:0","l":6,"lvl":"hard","type":"num","ctx":"Шешім саны. Жауапты бүтін санмен жазыңыз.","q":"$\\sin x+\\cos x=1$ теңдеуінің $[0;2\\pi)$ аралығындағы шешімдері неше?","a":2},{"id":"m1-6-count:1","l":6,"lvl":"hard","type":"num","ctx":"Шешім саны. Жауапты бүтін санмен жазыңыз.","q":"$\\sin2x=\\sin x$ теңдеуінің $[0;2\\pi)$ аралығындағы шешімдері неше?","a":4},{"id":"m1-6-inverse:0","l":6,"lvl":"hard","type":"num","ctx":"Кері функциялардың композициясы. Жауапты өрнекпен жазыңыз (мысалы, pi/6, 4/5).","q":"$\\arcsin\\left(\\sin\\dfrac{5\\pi}{6}\\right)$","a":"pi/6"},{"id":"m1-6-inverse:1","l":6,"lvl":"hard","type":"num","ctx":"Кері функциялардың композициясы. Жауапты өрнекпен жазыңыз (мысалы, pi/6, 4/5).","q":"$\\sin\\left(\\arccos\\dfrac35\\right)$","a":"4/5"},{"id":"m1-6-inverse:2","l":6,"lvl":"hard","type":"num","ctx":"Кері функциялардың композициясы. Жауапты өрнекпен жазыңыз (мысалы, pi/6, 4/5).","q":"$\\cos\\left(2\\arctan\\dfrac12\\right)$","a":"3/5"},{"id":"m1-6-tf-hard:0","l":6,"lvl":"hard","type":"tf","ctx":"Түсіну: теңдеулер мен кері функциялар. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$\\arccos x=\\arcsin x+\\dfrac{\\pi}{2}$.","a":false,"e":"Жалған: дұрысы $\\arcsin x+\\arccos x=\\frac{\\pi}{2}$, яғни $\\arccos x=\\frac{\\pi}{2}-\\arcsin x$."},{"id":"m1-6-tf-hard:1","l":6,"lvl":"hard","type":"tf","ctx":"Түсіну: теңдеулер мен кері функциялар. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$\\cos x=\\cos\\alpha$ теңдеуінің шешімдері $x=\\pm\\alpha+2\\pi k$.","a":true,"e":"Ақиқат: бірлік шеңбердегі $\\alpha$ және $-\\alpha$ нүктелерінің абсциссалары бірдей."},{"id":"m1-6-tf-hard:2","l":6,"lvl":"hard","type":"tf","ctx":"Түсіну: теңдеулер мен кері функциялар. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$\\sin x\\cos x=\\cos x$ теңдеуін $\\cos x$-ке қысқартуға болады.","a":false,"e":"Жалған: $\\cos x=0$ болуы мүмкін, шешімдер жоғалады. Жіктеу керек: $\\cos x(\\sin x-1)=0$."},{"id":"m1-6-tf-hard:3","l":6,"lvl":"hard","type":"tf","ctx":"Түсіну: теңдеулер мен кері функциялар. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"Шешімі жоқ: $\\sin x+\\cos x=\\sqrt3$.","a":true,"e":"Ақиқат: $\\sin x+\\cos x=\\sqrt2\\sin(x+\\frac{\\pi}{4})\\le\\sqrt2<\\sqrt3$."},{"id":"w5-q0","l":6,"lvl":"quiz","type":"choice","q":"y = sin 3x функциясының негізгі периоды қандай?","o":["π/3","3π","2π","2π/3"],"a":3,"e":"T = 2π/|ω| = 2π/3."},{"id":"w5-q1","l":6,"lvl":"quiz","type":"choice","q":"sin 15° · cos 15° неге тең?","o":["1/2","1/4","√3/4","1/8"],"a":1,"e":"sin 15° cos 15° = ½ sin 30° = 1/4."},{"id":"w5-q2","l":6,"lvl":"quiz","type":"choice","q":"arcsin(−1/2) неге тең?","o":["−π/6","π/6","−π/3","7π/6"],"a":0,"e":"sin(−π/6) = −1/2, және −π/6 ∈ [−π/2; π/2]."},{"id":"w5-q3","l":6,"lvl":"quiz","type":"choice","q":"sin x = 1/3 болса, cos 2x неге тең?","o":["1/9","2/3","−7/9","7/9"],"a":3,"e":"cos 2x = 1 − 2 sin² x = 1 − 2/9 = 7/9."},{"id":"w5-q4","l":6,"lvl":"quiz","type":"choice","q":"sin x = 1/2 теңдеуінің жалпы шешімі қайсы?","o":["(−1)ᵏ π/6 + πk","±π/6 + 2πk","π/6 + πk","π/3 + 2πk"],"a":0,"e":"x = (−1)ᵏ arcsin(1/2) + πk = (−1)ᵏ π/6 + πk, яғни π/6 + 2πn және 5π/6 + 2πn."},{"id":"w5-q5","l":6,"lvl":"quiz","type":"choice","q":"3 sin x + 4 cos x өрнегінің ең үлкен мәні қандай?","o":["7","5","√7","12"],"a":1,"e":"R = √(3² + 4²) = 5, мәндер жиыны [−5; 5]."},{"id":"w5-q6","l":6,"lvl":"quiz","type":"choice","q":"arcsin(sin(5π/6)) неге тең?","o":["5π/6","−π/6","π/6","π/3"],"a":2,"e":"sin(5π/6) = 1/2, arcsin(1/2) = π/6. Арксинус мәні [−π/2; π/2] аралығында."},{"id":"w5-q7","l":6,"lvl":"quiz","type":"choice","q":"Қай теңдік ЖАЛҒАН?","o":["cos 2x = 2cos² x − 1","sin 2x = 2 sin x cos x","arcsin x + arccos x = π/2 (|x| ≤ 1)","sin(α + β) = sin α + sin β"],"a":3,"e":"Дұрысы sin(α + β) = sin α cos β + cos α sin β. α = β = π/2 үшін сол жағы 0, оң жағы 2."},{"id":"m1-7-sums:0","l":7,"lvl":"easy","type":"num","ctx":"Қарапайым қосындылар. Жауапты бүтін санмен жазыңыз.","q":"$1+2+3+\\dots+100$","a":5050},{"id":"m1-7-sums:1","l":7,"lvl":"easy","type":"num","ctx":"Қарапайым қосындылар. Жауапты бүтін санмен жазыңыз.","q":"$\\sum_{k=1}^{5}k^2$","a":55},{"id":"m1-7-sums:2","l":7,"lvl":"easy","type":"num","ctx":"Қарапайым қосындылар. Жауапты бүтін санмен жазыңыз.","q":"$\\sum_{k=1}^{4}(2k+1)$","a":24},{"id":"m1-7-tf:0","l":7,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$\\sum_{k=1}^{n}k^2=\\left(\\sum_{k=1}^{n}k\\right)^2$ барлық $n$ үшін.","a":false,"e":"Жалған: $n=2$: $1+4=5$, ал $(1+2)^2=9$. Тек текшелер үшін $\\sum k^3=\\left(\\sum k\\right)^2$ орындалады."},{"id":"m1-7-tf:1","l":7,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"Арифметикалық прогрессияда көрші мүшелердің айырмасы тұрақты.","a":true,"e":"Ақиқат: $a_{n+1}-a_n=d$ анықтама бойынша."},{"id":"m1-7-tf:2","l":7,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$1+\\frac12+\\frac14+\\dots=2$.","a":true,"e":"Ақиқат: $b_1=1$, $q=\\frac12$, $S=\\frac{1}{1-1/2}=2$."},{"id":"m1-7-tf:3","l":7,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$1+2+4+8+\\dots=-1$, себебі $\\frac{1}{1-2}=-1$.","a":false,"e":"Жалған: $|q|=2\\ge1$, формула қолданылмайды; қосынды шексіз өседі."},{"id":"m1-7-tf:4","l":7,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$\\sum_{k=0}^{10}1=10$.","a":false,"e":"Жалған: индекс 0-ден 10-ға дейін 11 мән қабылдайды, қосынды 11."},{"id":"m1-7-pick:0","l":7,"lvl":"easy","type":"choice","ctx":"Прогрессия параметрлері. Дұрыс жауапты таңдаңыз.","q":"$a_1=5$, $d=-2$ арифметикалық прогрессияның $a_{10}$ мүшесі қандай?","o":["$-15$","$-13$","$-23$","$25$"],"a":1,"e":"$a_{10}=a_1+9d=5-18=-13$."},{"id":"m1-7-pick:1","l":7,"lvl":"easy","type":"choice","ctx":"Прогрессия параметрлері. Дұрыс жауапты таңдаңыз.","q":"Қай тізбектер геометриялық прогрессия? Дұрыс жауаптардың барлығын белгілеңіз.","o":["$1,\\ 3,\\ 9,\\ 27,\\ \\dots$","$2,\\ 4,\\ 6,\\ 8,\\ \\dots$","$8,\\ -4,\\ 2,\\ -1,\\ \\dots$","$1,\\ 4,\\ 9,\\ 16,\\ \\dots$"],"a":[0,2],"e":"Қатынасы: $3$ және $-\\frac12$ тұрақты. Екінші - арифметикалық ($d=2$), төртіншіде қатынас тұрақты емес."},{"id":"m1-7-pick:2","l":7,"lvl":"easy","type":"choice","ctx":"Прогрессия параметрлері. Дұрыс жауапты таңдаңыз.","q":"$\\sum_{k=2}^{6}k$ неге тең?","o":["$21$","$20$","$15$","$18$"],"a":1,"e":"$2+3+4+5+6=20$ (1-ден 6-ға дейінгі қосынды $21$ минус $1$)."},{"id":"m1-7-gp:0","l":7,"lvl":"easy","type":"num","ctx":"Геометриялық прогрессия. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$b_1=3$, $q=2$ болса, $b_5=\\ ?$","a":48},{"id":"m1-7-gp:1","l":7,"lvl":"easy","type":"num","ctx":"Геометриялық прогрессия. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$1+2+4+8$ қосындысы.","a":15},{"id":"m1-7-gp:2","l":7,"lvl":"easy","type":"num","ctx":"Геометриялық прогрессия. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$1+\\frac13+\\frac19+\\dots$ шексіз қосындысы.","a":"3/2"},{"id":"m1-7-closed:0","l":7,"lvl":"medium","type":"expr","ctx":"Қосындының жабық формуласы. Жауапты $n$ арқылы жазыңыз (көбейту n*(n+1), дәреже n^2, бөлшек: n*(n+1)/2).","q":"$\\sum_{k=1}^{n}(2k-1)$ қосындысын $n$ арқылы жазыңыз.","a":"n^2","vars":["n"],"dom":[1,9]},{"id":"m1-7-closed:1","l":7,"lvl":"medium","type":"expr","ctx":"Қосындының жабық формуласы. Жауапты $n$ арқылы жазыңыз (көбейту n*(n+1), дәреже n^2, бөлшек: n*(n+1)/2).","q":"$\\sum_{k=1}^{n}k(k+1)$ қосындысын $n$ арқылы жазыңыз.","a":"n*(n+1)*(n+2)/3","vars":["n"],"dom":[1,9]},{"id":"m1-7-closed:2","l":7,"lvl":"medium","type":"expr","ctx":"Қосындының жабық формуласы. Жауапты $n$ арқылы жазыңыз (көбейту n*(n+1), дәреже n^2, бөлшек: n*(n+1)/2).","q":"Арифметикалық прогрессияда $a_3=7$, $a_8=22$. $a_n=\\ ?$","a":"3*n-2","vars":["n"],"dom":[1,9]},{"id":"m1-7-calc:0","l":7,"lvl":"medium","type":"num","ctx":"Қосындыларды есептеу. Жауапты санмен жазыңыз.","q":"$\\sum_{k=1}^{30}(4k-1)$","a":1830},{"id":"m1-7-calc:1","l":7,"lvl":"medium","type":"num","ctx":"Қосындыларды есептеу. Жауапты санмен жазыңыз.","q":"$6+2+\\frac23+\\dots$ шексіз қосындысы.","a":9},{"id":"m1-7-calc:2","l":7,"lvl":"medium","type":"num","ctx":"Қосындыларды есептеу. Жауапты санмен жазыңыз.","q":"$\\sum_{k=1}^{99}\\dfrac1{k(k+1)}$ (бөлшекпен, мысалы 99/100)","a":"99/100"},{"id":"m1-7-recur:0","l":7,"lvl":"medium","type":"matrix","ctx":"Рекуррентті тізбек. Алғашқы 5 мүшені жол түрінде жазыңыз.","q":"$a_1=3$, $a_{n+1}=2a_n-1$ тізбегінің алғашқы бес мүшесі.","orient":"row","name":"$a_1\\ldots a_5$:","a":[3,5,9,17,33]},{"id":"m1-7-recur:1","l":7,"lvl":"medium","type":"matrix","ctx":"Рекуррентті тізбек. Алғашқы 5 мүшені жол түрінде жазыңыз.","q":"Фибоначчи: $F_1=F_2=1$, $F_{n+1}=F_n+F_{n-1}$. $F_1,\\dots,F_8$.","orient":"row","name":"$F_1\\ldots F_8$:","a":[1,1,2,3,5,8,13,21]},{"id":"m1-7-induct:0","l":7,"lvl":"medium","type":"choice","ctx":"Индукция дәлелінің дұрыстығы. Дұрыс жауапты таңдаңыз.","q":"Индукция дәлелінде қайсысы міндетті? Дұрыс жауаптардың барлығын белгілеңіз.","o":["база ($n=n_0$ үшін тексеру)","қадам: $P(k)\\Rightarrow P(k+1)$","$n=1,2,3,4,5$ жағдайларды тексеру жеткілікті","қадамда индукциялық жорамалды қолдану"],"a":[0,1,3],"e":"Бірнеше жағдайды тексеру дәлел емес ($n^2+n+41$ мысалы). Қалған үшеуі індукцияның құрамдас бөліктері."},{"id":"m1-7-induct:1","l":7,"lvl":"medium","type":"choice","ctx":"Индукция дәлелінің дұрыстығы. Дұрыс жауапты таңдаңыз.","q":"«$2^n&gt;n^2$» тұжырымын индукциямен дәлелдеуде базаны қай $n$-нен бастау керек?","o":["$n=1$","$n=2$","$n=3$","$n=5$"],"a":3,"e":"$n=2$ үшін $4=4$, $n=3$ үшін $8&lt;9$, $n=4$ үшін $16=16$ - тұжырым орындалмайды. $n=5$ үшін $32&gt;25$ және одан кейін қадам жұмыс істейді."},{"id":"m1-7-annuity:0","l":7,"lvl":"hard","type":"num","ctx":"Қор жинау. Жауапты санмен жазыңыз.","q":"Әр айдың соңында $50\\,000$ теңге, айлық мөлшерлеме $1\\%$. 24 айдан кейінгі сома қанша? (бүтін теңгеге дейін)","a":"50000*(1.01^24-1)/0.01","tol":0.5,"unit":"теңге"},{"id":"m1-7-annuity:1","l":7,"lvl":"hard","type":"num","ctx":"Қор жинау. Жауапты санмен жазыңыз.","q":"Жылына $r=8\\%$ өсетін салымға әр жылдың соңында $200\\,000$ теңге салынады. 5 жылдан кейінгі сома (бүтін теңгеге дейін).","a":"200000*(1.08^5-1)/0.08","tol":0.5,"unit":"теңге"},{"id":"m1-7-decimal:0","l":7,"lvl":"hard","type":"num","ctx":"Периодты ондық бөлшек. Жауапты қысқармайтын бөлшекпен жазыңыз.","q":"$0{,}(36)=0{,}363636\\ldots$ санын жай бөлшекке айналдырыңыз.","a":"4/11"},{"id":"m1-7-decimal:1","l":7,"lvl":"hard","type":"num","ctx":"Периодты ондық бөлшек. Жауапты қысқармайтын бөлшекпен жазыңыз.","q":"$0{,}1(6)=0{,}1666\\ldots$ санын жай бөлшекке айналдырыңыз.","a":"1/6"},{"id":"m1-7-sumform:0","l":7,"lvl":"hard","type":"expr","ctx":"Қосындыны табу. Жауапты $n$ арқылы жазыңыз.","q":"$\\sum_{k=1}^{n}k(k+2)$ қосындысын $n$ арқылы жазыңыз.","a":"n*(n+1)*(2*n+7)/6","vars":["n"],"dom":[1,9]},{"id":"m1-7-ineq:0","l":7,"lvl":"hard","type":"num","ctx":"Бағалау: ең кіші n. Жауапты бүтін санмен жазыңыз.","q":"$2^n&gt;n^3$ теңсіздігі барлық $n\\ge n_0$ үшін орындалатындай ең кіші $n_0$ қандай?","a":10},{"id":"m1-7-tf-hard:0","l":7,"lvl":"hard","type":"tf","ctx":"Түсіну: индукция және қосындылар. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"Егер $P(n)$ үшін қадам ($P(k)\\Rightarrow P(k+1)$) дәлелденсе, онда $P(n)$ барлық $n$ үшін дұрыс.","a":false,"e":"Жалған: база да керек. «$n^2+n+1$ саны жұп» тұжырымының қадамы орындалады, бірақ база жоқ."},{"id":"m1-7-tf-hard:1","l":7,"lvl":"hard","type":"tf","ctx":"Түсіну: индукция және қосындылар. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$\\sum_{k=1}^{n}\\big(a_{k+1}-a_k\\big)=a_{n+1}-a_1$.","a":true,"e":"Ақиқат: телескоптық қосынды, ішкі мүшелер қысқарады."},{"id":"m1-7-tf-hard:2","l":7,"lvl":"hard","type":"tf","ctx":"Түсіну: индукция және қосындылар. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$|q|&lt;1$ геометриялық қосындысы үшін $S=\\frac{b_1}{1-q}$ ортасына дейін қосуға да сәйкес келеді.","a":false,"e":"Жалған: $S$ - шексіз қосындының мәні. $n$ мүшенің қосындысы $\\frac{b_1(1-q^n)}{1-q}$, ол $S$-ке тең емес (тек жақындайды)."},{"id":"m1-7-tf-hard:3","l":7,"lvl":"hard","type":"tf","ctx":"Түсіну: индукция және қосындылар. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$\\sin1+\\sin2+\\dots$ қосындысына арифметикалық прогрессия формуласын қолдануға болады.","a":false,"e":"Жалған: $\\sin k$ мәндерінің көрші айырмасы тұрақты емес."},{"id":"w6-q0","l":7,"lvl":"quiz","type":"choice","q":"1 + 2 + 3 + … + 100 қосындысы неге тең?","o":["5000","10100","5050","5150"],"a":2,"e":"S = 100 · 101 / 2 = 5050 (Гаусс жұптауы)."},{"id":"w6-q1","l":7,"lvl":"quiz","type":"choice","q":"Арифметикалық прогрессияда a₁ = 5, d = −2. a₁₀ неге тең?","o":["−13","−15","23","−23"],"a":0,"e":"a₁₀ = a₁ + 9d = 5 − 18 = −13."},{"id":"w6-q2","l":7,"lvl":"quiz","type":"choice","q":"Геометриялық прогрессия 3, 6, 12, … үшін b₆ неге тең?","o":["48","192","96","72"],"a":2,"e":"q = 2, b₆ = 3 · 2⁵ = 96."},{"id":"w6-q3","l":7,"lvl":"quiz","type":"choice","q":"8 + 4 + 2 + 1 + … шексіз қосындысы неге тең?","o":["12","32","∞","16"],"a":3,"e":"b₁ = 8, q = 1/2, S = 8/(1 − 1/2) = 16."},{"id":"w6-q4","l":7,"lvl":"quiz","type":"choice","q":"∑ₖ₌₁¹⁰ k² қосындысы неге тең?","o":["385","55","3025","330"],"a":0,"e":"10 · 11 · 21 / 6 = 385."},{"id":"w6-q5","l":7,"lvl":"quiz","type":"choice","q":"0,(3) = 0,333… периодты бөлшегі қай жай бөлшекке тең?","o":["3/10","1/3","3/100","33/100"],"a":1,"e":"b₁ = 3/10, q = 1/10, S = (3/10)/(9/10) = 1/3."},{"id":"w6-q6","l":7,"lvl":"quiz","type":"choice","q":"Индукцияны дәлелдеуде қайсысы міндетті?","o":["тек база","тек индукциялық қадам","база және индукциялық қадам","10 жағдайды тексеру"],"a":2,"e":"Домино ұқсастығы: бірінші тас құлауы (база) және әр тас келесісін құлатуы (қадам)."},{"id":"w6-q7","l":7,"lvl":"quiz","type":"choice","q":"∑ₖ₌₁⁹ 1/(k(k+1)) қосындысы неге тең?","o":["9/10","1/10","8/9","10/9"],"a":0,"e":"Телескоп: 1/k − 1/(k+1). Қосынды 1 − 1/10 = 9/10."}];
